window.NOOR_CATALOG={"schemaVersion":1,"version":"1.0.0","brand":{"title":"استوديو نور التعليمي","author":"الأستاذ أحمد الضامري"},"courses":[{"id":"g7-it-s1","grade":7,"subject":"تقنية المعلومات","semester":1,"title":"تقنية المعلومات · السابع","status":"ready","units":[{"id":"g7-u1","title":"تطور التقنية والذكاء الاصطناعي","noorTitle":"تطور التقنية والذكاء الاصطناعي","number":1,"officialPeriods":9,"source":"دليل المعلم للسابع — الفصل الأول، ص25–51","lessons":[{"id":"g7-u1-l1","title":"تطور الحواسيب والتقنيات الناشئة","noorTitle":"تطور الحواسيب والتقنيات الناشئة","officialPeriods":3,"source":"دليل المعلم ص25–29","goalSource":"noor-observed","quiz":[{"question":"التقنية المرتبطة بالجيل الثاني هي…","options":["الصمامات المفرغة","الترانزستورات","المعالجات الدقيقة"],"answer":1,"explanation":"الترتيب المطلوب لهذه البطاقات: الصمام المفرغ ← الترانزستور ← المعالج الدقيق. يتناول التفسير الحجم أو السرعة أو كفاءة الطاقة؛ وبين الترانزستور والمعالج مرحلة الدوائر المتكاملة."},{"question":"ما المرحلة التي تسبق تدريب النموذج؟","options":["التنبؤ","معالجة البيانات","عرض النتيجة فقط"],"answer":1,"explanation":"جمع البيانات ← معالجتها ← تدريب النموذج ← التنبؤ. مثال: نظام توصية يستخدم سجل التفضيلات وقد يقترح محتوى غير مناسب إذا كانت بياناته غير كافية."},{"question":"إضافة عناصر رقمية إلى المشهد الحقيقي مثال على…","options":["الواقع المعزز","الواقع الافتراضي","الترانزستور"],"answer":0,"explanation":"الواقع الافتراضي، الواقع المعزز، الحوسبة السحابية. إنترنت الأشياء يربط أجهزة تتبادل البيانات؛ القياسات الحيوية تعتمد خصائص جسمية مثل البصمة."}],"meetings":[{"id":"g7-u1-l1-m1","part":"1/2","title":"رحلة أجيال الحاسوب + تعلم الآلة وتطبيقات الذكاء الاصطناعي","periods":[{"title":"رحلة أجيال الحاسوب","outcomes":[{"id":"31900","text":"التعرف إلى أجيال الحاسوب وتطورها."}],"reinforcement":false,"warm":"اعرض صور الحواسيب من الكتاب. فكر فرديًا: أيها أقدم؟ ما دليلك؟ ثم تبادل رأيك مع زميل. استرجع صفحة «هل تذكر؟» دون إلزام الطالب بحفظ التواريخ.","explain":"الصمام المفرغ، الترانزستور، الدوائر المتكاملة، المعالج الدقيق، الذكاء الاصطناعي، الحوسبة الكمومية. يعرض المعلم صور الأجيال وتقنياتها وفق الكتاب: الصمامات ثم الترانزستورات ثم الدوائر المتكاملة ثم المعالجات الدقيقة، ويقدم التطورات الحديثة بأسلوب مبسط.","example":"مثال: الانتقال من الصمامات إلى الترانزستورات تغير في تقنية المكونات، وليس في لون الجهاز. اكتب أثرين لهذا التطور كما يوضحهما الكتاب.","task":"تعمل مجموعات من أربعة: قارئ، مرتب، مبرر، مقرر. ترتب بطاقات الأجيال، وتربط كل جيل بالتقنية المناسبة وتفسير التحسن. تتبادل المجموعات التحقق.","misconception":"الجيل الأحدث يعني تغيير شكل الحاسوب فقط.","repair":"اربط كل جيل بتقنية التصنيع وما تحسن في الحجم والطاقة والأداء، ثم اطلب مقارنة مفسرة بدل حفظ الاسم وحده.","game":"تحدي الخط الزمني: تعمل مجموعات من أربعة: قارئ، مرتب، مبرر، مقرر. ترتب بطاقات الأجيال، وتربط كل جيل بالتقنية المناسبة وتفسير التحسن. تتبادل المجموعات التحقق.","evidence":"ألاحظ ترتيب البطاقات وصحة الربط. أطلب تبريرًا من طالب غير مقرر المجموعة. معيار النجاح: ترتيب صحيح ومقارنة مفسرة، مع تصحيح الخطأ فورًا.","question":"رتب: المعالج الدقيق، الصمام المفرغ، الترانزستور. ثم وضح كيف تحسنت الحواسيب من جيل إلى آخر.","answer":"الترتيب المطلوب لهذه البطاقات: الصمام المفرغ ← الترانزستور ← المعالج الدقيق. يتناول التفسير الحجم أو السرعة أو كفاءة الطاقة؛ وبين الترانزستور والمعالج مرحلة الدوائر المتكاملة.","steps":[["5 دقائق","انطلاق","يناقش المعلم الفروق في الحجم والسرعة والطاقة. يصف الطلبة ما يلاحظونه، ويُجمع تصورهم الأولي."],["10 دقائق","اكتشف التطور","الصمام المفرغ، الترانزستور، الدوائر المتكاملة، المعالج الدقيق، الذكاء الاصطناعي، الحوسبة الكمومية. يعرض المعلم صور الأجيال وتقنياتها وفق الكتاب: الصمامات ثم الترانزستورات ثم الدوائر المتكاملة ثم المعالجات الدقيقة، ويقدم التطورات الحديثة بأسلوب مبسط. مثال محلل: مثال: الانتقال من الصمامات إلى الترانزستورات تغير في تقنية المكونات، وليس في لون الجهاز. اكتب أثرين لهذا التطور كما يوضحهما الكتاب."],["15 دقيقة","تحدي الخط الزمني","تعمل مجموعات من أربعة: قارئ، مرتب، مبرر، مقرر. ترتب بطاقات الأجيال، وتربط كل جيل بالتقنية المناسبة وتفسير التحسن. تتبادل المجموعات التحقق."],["5 دقائق","قارن وفسر","يناقش الطلبة لماذا يمثل تقليل الحجم والحرارة واستهلاك الطاقة تطورًا مهمًا؛ يصحح المعلم الخلط بين الأجيال."],["5 دقائق","بطاقة خروج","يرتب كل طالب ثلاث تقنيات ويكتب فرقًا بين جيلين؛ تُجمع الإجابات لتحديد الدعم التالي."]]},{"title":"تعلم الآلة وتطبيقات الذكاء الاصطناعي","outcomes":[{"id":"31920","text":"شرح كيفية عمل تعلم الآلة."},{"id":"31901","text":"التعرف إلى تطبيقات الذكاء الاصطناعي في الحياة اليومية."},{"id":"31902","text":"التعرف إلى تحديات الذكاء الاصطناعي."}],"reinforcement":false,"warm":"اعرض موقفًا من توقعات الطقس: لماذا يحتاج الصياد أو المزارع أو الطيار إلى توقع دقيق؟ يكتب كل طالب قرارًا يتأثر بالتوقع.","explain":"جمع البيانات، معالجة البيانات، تدريب النموذج، التنبؤ، أنظمة التوصية، المساعدات الصوتية. يشرح المعلم مثال الكتاب على المراحل: جمع البيانات، معالجتها، تدريب النموذج، التنبؤ. يميز الطلبة بين التدريب واستخدام النموذج.","example":"صنف أمثلة تدريب مبسطة لفئتين ثم اختبر مثالًا جديدًا. اشرح أثر قلة الأمثلة أو عدم تنوعها، ولا تدع أن المحاكاة تدرب نموذجًا حقيقيًا.","task":"تصنف المجموعات بطاقات أمثلة ثم تختبر مثالًا جديدًا. تمثل المحاكاة أثر البيانات في التنبؤ؛ يؤكد المعلم أنها تبسيط وليست تشغيلًا فعليًا لخوارزمية.","misconception":"كل نظام ذكاء اصطناعي هو تعلم آلة، وكل تعلم آلة يعمل دون بيانات.","repair":"وضح أن تعلم الآلة مجال ضمن الذكاء الاصطناعي ويتعلم أنماطًا من بيانات؛ قارن نظامًا يعمل بقواعد محددة بنظام يتعلم أمثلة.","game":"مختبر البيانات الورقي: تصنف المجموعات بطاقات أمثلة ثم تختبر مثالًا جديدًا. تمثل المحاكاة أثر البيانات في التنبؤ؛ يؤكد المعلم أنها تبسيط وليست تشغيلًا فعليًا لخوارزمية.","evidence":"أتحقق من ترتيب مراحل تعلم الآلة، وربط التطبيق بالبيانات، وتفسير سبب الخطأ. أستخدم سؤالًا قصيرًا بعد كل مرحلة وأعيد النمذجة عند الخلط.","question":"رتب مراحل تعلم الآلة، ثم اختر تطبيقًا واذكر بيانات يستخدمها وخطأ محتملًا قد يرتكبه.","answer":"جمع البيانات ← معالجتها ← تدريب النموذج ← التنبؤ. مثال: نظام توصية يستخدم سجل التفضيلات وقد يقترح محتوى غير مناسب إذا كانت بياناته غير كافية.","steps":[["5 دقائق","استرجع","مراجعة سريعة للتطور الحديث في الحاسوب، والانتقال إلى مفهوم الذكاء الاصطناعي."],["10 دقائق","نمذج تعلم الآلة","جمع البيانات، معالجة البيانات، تدريب النموذج، التنبؤ، أنظمة التوصية، المساعدات الصوتية. يشرح المعلم مثال الكتاب على المراحل: جمع البيانات، معالجتها، تدريب النموذج، التنبؤ. يميز الطلبة بين التدريب واستخدام النموذج. مثال محلل: صنف أمثلة تدريب مبسطة لفئتين ثم اختبر مثالًا جديدًا. اشرح أثر قلة الأمثلة أو عدم تنوعها، ولا تدع أن المحاكاة تدرب نموذجًا حقيقيًا."],["15 دقيقة","مختبر البيانات الورقي","تصنف المجموعات بطاقات أمثلة ثم تختبر مثالًا جديدًا. تمثل المحاكاة أثر البيانات في التنبؤ؛ يؤكد المعلم أنها تبسيط وليست تشغيلًا فعليًا لخوارزمية."],["5 دقائق","اكتشف التحدي","تختار كل مجموعة تطبيقًا: توصيات أو مساعد صوتي أو تعرف على الصور، وتحدد البيانات والأخطاء المحتملة وحدود فهم السياق واللغة والبيانات غير الواضحة."],["5 دقائق","تقويم فردي","يرتب الطلبة المراحل ويعطون مثالًا وتحديًا؛ يقارن المعلم الإجابات بمعايير النجاح."]]}],"goalBinding":"official","parentNote":"أنشئ مقارنة قصيرة بين جهاز قديم وحديث اعتمادًا على كتاب الطالب."},{"id":"g7-u1-l1-m2","part":"2/2","title":"التقنيات الناشئة وتطبيقاتها + مختبر المقارنة وتثبيت قرارات التقنية","periods":[{"title":"التقنيات الناشئة وتطبيقاتها","outcomes":[{"id":"31903","text":"التمييز بين أنواع التقنيات الناشئة وتطبيقاتها العملية."}],"reinforcement":false,"warm":"اعرض صورتين: بيئة افتراضية كاملة وعناصر رقمية مضافة إلى العالم الحقيقي. ما الفرق؟ يكتب الطلبة توقعاتهم قبل المناقشة.","explain":"الواقع الافتراضي، الواقع المعزز، الحوسبة السحابية، إنترنت الأشياء، القياسات الحيوية، التقنيات المساعدة. يقارن المعلم والطلبة بين الواقع الافتراضي والمعزز من حيث البيئة والأدوات، مستخدمين أمثلة الكتاب.","example":"قارن موقف تجربة تعليمية افتراضية بموقف استخدام جهاز متصل. ماذا تضيف التقنية في كل موقف؟ لا تقترح استخدامها إذا لم تضف فائدة واضحة.","task":"تتناوب المجموعات على بطاقات: الحوسبة السحابية، إنترنت الأشياء، القياسات الحيوية، التقنيات المساعدة. لكل بطاقة: تعريف مبسط، تطبيق، فائدة، وموقف يقتضي مسؤولية.","misconception":"تسمية تقنية ناشئة تكفي لإثبات فائدتها في أي موقف.","repair":"اطلب تحديد الحاجة أولًا، ثم ربط الخاصية بالمهمة وذكر حد للاستخدام أو معلومة تحتاج إلى تحقق.","game":"محطات التقنية: تتناوب المجموعات على بطاقات: الحوسبة السحابية، إنترنت الأشياء، القياسات الحيوية، التقنيات المساعدة. لكل بطاقة: تعريف مبسط، تطبيق، فائدة، وموقف يقتضي مسؤولية.","evidence":"تقييم جدول المقارنة وبطاقات المحطات: صحة التقنية، مناسبة المثال، وضوح التفسير. أصحح الخلط بين التخزين السحابي ومكونات الجهاز.","question":"بيئة رقمية كاملة، إضافة معلومات إلى المشهد الحقيقي، ومشاركة ملفات عبر الإنترنت: سمِّ التقنية المناسبة لكل حالة.","answer":"الواقع الافتراضي، الواقع المعزز، الحوسبة السحابية. إنترنت الأشياء يربط أجهزة تتبادل البيانات؛ القياسات الحيوية تعتمد خصائص جسمية مثل البصمة.","steps":[["5 دقائق","انطلاق","ربط الذكاء الاصطناعي بمجموعة أوسع من التقنيات الناشئة."],["10 دقائق","قارن","الواقع الافتراضي، الواقع المعزز، الحوسبة السحابية، إنترنت الأشياء، القياسات الحيوية، التقنيات المساعدة. يقارن المعلم والطلبة بين الواقع الافتراضي والمعزز من حيث البيئة والأدوات، مستخدمين أمثلة الكتاب. مثال محلل: قارن موقف تجربة تعليمية افتراضية بموقف استخدام جهاز متصل. ماذا تضيف التقنية في كل موقف؟ لا تقترح استخدامها إذا لم تضف فائدة واضحة."],["15 دقيقة","محطات التقنية","تتناوب المجموعات على بطاقات: الحوسبة السحابية، إنترنت الأشياء، القياسات الحيوية، التقنيات المساعدة. لكل بطاقة: تعريف مبسط، تطبيق، فائدة، وموقف يقتضي مسؤولية."],["5 دقائق","دافع عن اختيارك","تعرض المجموعات كيف تسهل التقنية الحياة، وكيف تساعد قارئات الشاشة أو أدوات برايل أو توليد الكلام الأشخاص ذوي الإعاقة."],["5 دقائق","فرز فردي","يطابق الطالب ثلاث حالات بتقنياتها ويشرح فرق الواقعين؛ يُستكمل تقويم الدرس الأول."]]},{"title":"مختبر المقارنة وتثبيت قرارات التقنية","outcomes":[{"id":"31903","text":"التمييز بين أنواع التقنيات الناشئة وتطبيقاتها العملية."}],"reinforcement":true,"warm":"استرجع أجيال الحاسوب بمقارنة تقنية واحدة وأثرها، ثم اعرض حالة استخدام لتقنية ناشئة.","explain":"هذه حصة تطبيق إضافية لإكمال اللقاء الثاني بعد حصص الدليل الثلاث. نربط خصائص التقنية بموقف استخدام، ونراجع أثرها وفائدتها وحدودها، دون ادعاء إضافة مخرج رسمي.","example":"بطاقة المقارنة تربط التقنية بحاجتك وتذكر فائدتها وقيد استخدامها؛ يحسنها الطالب بعد سؤال زميل.","task":"أعد بطاقة قرار: الحاجة، التقنية، فائدتها، قيد استخدامها، ومصدر التفسير. راجع بطاقة زميل ثم حسّن سببًا واحدًا.","misconception":"الحصول على جواب سريع يغني عن تفسير الاختيار.","repair":"استخدم بطاقة قرار تتضمن الحاجة والدليل والبديل؛ راجع الفهم قبل منح تعزيز مرتبط بالأداء.","game":"محطات التقنية: تتناوب المجموعات على بطاقات: الحوسبة السحابية، إنترنت الأشياء، القياسات الحيوية، التقنيات المساعدة. لكل بطاقة: تعريف مبسط، تطبيق، فائدة، وموقف يقتضي مسؤولية.","evidence":"تقييم جدول المقارنة وبطاقات المحطات: صحة التقنية، مناسبة المثال، وضوح التفسير. أصحح الخلط بين التخزين السحابي ومكونات الجهاز.","question":"كيف تميز معرفة اسم التقنية عن فهم استخدامها؟","answer":"بتفسير الحاجة والفائدة والحدود مع مثال مناسب، وليس بالتسمية وحدها.","steps":[["5 دقائق","استرجاع","استرجع أجيال الحاسوب بمقارنة تقنية واحدة وأثرها، ثم اعرض حالة استخدام لتقنية ناشئة."],["10 دقائق","نمذجة مقارنة","هذه حصة تطبيق إضافية لإكمال اللقاء الثاني بعد حصص الدليل الثلاث. نربط خصائص التقنية بموقف استخدام، ونراجع أثرها وفائدتها وحدودها، دون ادعاء إضافة مخرج رسمي. مثال محلل: بطاقة المقارنة تربط التقنية بحاجتك وتذكر فائدتها وقيد استخدامها؛ يحسنها الطالب بعد سؤال زميل."],["15 دقيقة","مختبر القرار","أعد بطاقة قرار: الحاجة، التقنية، فائدتها، قيد استخدامها، ومصدر التفسير. راجع بطاقة زميل ثم حسّن سببًا واحدًا."],["7 دقائق","مراجعة زملاء","جدول مقارنة وصور للدعم؛ إثراء: حلل فائدة ومخاطر تقنية مختارة."],["3 دقائق","بطاقة خروج","كيف تميز معرفة اسم التقنية عن فهم استخدامها؟"]]}],"goalBinding":"official","parentNote":"حل التدريبات المناسبة للدرس الأول في كتاب الطالب، واكتب تقنية واحدة يمكن أن تساعد شخصًا في مدرستك."}]},{"id":"g7-u1-l2","title":"الذكاء الاصطناعي التوليدي","noorTitle":"الذكاء الاصطناعي التوليدي","officialPeriods":2,"source":"دليل المعلم ص34–37","goalSource":"noor-observed","quiz":[{"question":"أفضل توجيه هو الذي…","options":["يحدد المطلوب بوضوح","يكون طويلًا دائمًا","لا يحدد المهمة"],"answer":0,"explanation":"مثال: اقترح ثلاث فوائد للمدن الذكية في فقرة عربية قصيرة تناسب الصف السابع، مع مثال لكل فائدة. الوضوح ناتج عن المهمة والجمهور وشكل الناتج."},{"question":"إذا كانت إجابة الأداة تبدو دقيقة…","options":["أنقلها فورًا","أتحقق منها بمصدر موثوق","لا أحتاج إلى مراجعتها"],"answer":1,"explanation":"قد تنشئ الأداة معلومات تبدو مقنعة لكنها غير صحيحة؛ نراجعها بمصدر موثوق ونصححها قبل الاستخدام ونراعي نسب المحتوى وخصوصية البيانات."}],"meetings":[{"id":"g7-u1-l2-m1","part":"1/1","title":"الذكاء الاصطناعي التوليدي والتوجيه + إنشاء المحتوى والتحقق والاستخدام المسؤول","periods":[{"title":"الذكاء الاصطناعي التوليدي والتوجيه","outcomes":[{"id":"31904","text":"التعرف إلى مفهوم الذكاء الاصطناعي التوليدي."},{"id":"31921","text":"التعرف إلى استخدامات الذكاء الاصطناعي التوليدي في الحياة اليومية."},{"id":"31922","text":"التعرف إلى مفهوم التوجيه."},{"id":"31923","text":"صياغة توجيهات واضحة."},{"id":"31924","text":"التعرف إلى مفهوم هندسة التوجيه."}],"reinforcement":false,"warm":"قارن بين أداة تتوقع نتيجة وأداة تنشئ نصًا جديدًا. ناقش الفرق، ثم اطرح توجيهًا غامضًا وآخر محددًا: أيهما أوضح؟","explain":"الذكاء الاصطناعي التوليدي، التوجيه، هندسة التوجيه، Gemini. يوضح المعلم واجهة الأداة وخطوات إدخال التوجيه وفق الكتاب. يعرض مثالًا منظمًا على موضوع المدن الذكية.","example":"قارن توجيهًا عامًا «اكتب موضوعًا» بتوجيه يحدد الموضوع والجمهور والشكل والطول. أيهما يساعد على إنتاج محتوى أقرب للمهمة ولماذا؟","task":"تكتب المجموعات توجيهًا يحدد المهمة والموضوع والجمهور وصيغة الناتج. يقارن الطلبة صياغة أولى وأخرى محسنة ويبررون التعديل.","misconception":"الذكاء الاصطناعي التوليدي يسترجع دائمًا حقيقة مؤكدة من مصدر واحد.","repair":"افصل بين توليد محتوى محتمل والتحقق من صحة معلومة. صغ طلبًا واضحًا ثم راجع الناتج والمصادر.","game":"ورشة التوجيه: تكتب المجموعات توجيهًا يحدد المهمة والموضوع والجمهور وصيغة الناتج. يقارن الطلبة صياغة أولى وأخرى محسنة ويبررون التعديل.","evidence":"أتحقق من احتواء التوجيه على مهمة واضحة وموضوع وجمهور أو تنسيق مناسب، ومن قدرة الطالب على شرح التعديل. لا أجعل طول النص وحده معيار الجودة.","question":"اكتب توجيهًا لإنشاء فقرة مناسبة لطلبة السابع عن المدن الذكية، وحدد عنصرين جعلاه واضحًا.","answer":"مثال: اقترح ثلاث فوائد للمدن الذكية في فقرة عربية قصيرة تناسب الصف السابع، مع مثال لكل فائدة. الوضوح ناتج عن المهمة والجمهور وشكل الناتج.","steps":[["5 دقائق","استرجاع","يربط المعلم الدرس بتعلم الآلة ويقدم فكرة توليد محتوى جديد."],["10 دقائق","عرض موجه","الذكاء الاصطناعي التوليدي، التوجيه، هندسة التوجيه، Gemini. يوضح المعلم واجهة الأداة وخطوات إدخال التوجيه وفق الكتاب. يعرض مثالًا منظمًا على موضوع المدن الذكية. مثال محلل: قارن توجيهًا عامًا «اكتب موضوعًا» بتوجيه يحدد الموضوع والجمهور والشكل والطول. أيهما يساعد على إنتاج محتوى أقرب للمهمة ولماذا؟"],["15 دقيقة","ورشة التوجيه","تكتب المجموعات توجيهًا يحدد المهمة والموضوع والجمهور وصيغة الناتج. يقارن الطلبة صياغة أولى وأخرى محسنة ويبررون التعديل."],["5 دقائق","تبادل ومراجعة","تراجع كل مجموعة توجيه زملائها باستخدام معيار الوضوح وتحديد المطلوب؛ ينفذ المعلم نموذجًا على الشاشة."],["5 دقائق","غلق","يكتب كل طالب تعريفًا للتوجيه وتوجيهًا مناسبًا؛ يقدم المعلم تغذية راجعة."]]},{"title":"إنشاء المحتوى والتحقق والاستخدام المسؤول","outcomes":[{"id":"31925","text":"اتباع إرشادات هندسة التوجيه الفعالة لتحسين التوجيهات والحصول على استجابات أفضل من الذكاء الاصطناعي."},{"id":"31926","text":"التحقق من صحة المعلومات المُولّدة بواسطة الذكاء الاصطناعي."},{"id":"31927","text":"التعرف إلى مفهوم هلوسة الذكاء الاصطناعي."},{"id":"31928","text":"اتباع إرشادات استخدام الذكاء الاصطناعي التوليدي بمسؤولية."},{"id":"31929","text":"استخدام الصور المُولّدة بالذكاء الاصطناعي بشكل أخلاقي ومسؤول."}],"reinforcement":false,"warm":"يعرض المعلم ادعاءً غير صحيح مصاغًا بثقة من نموذج تعليمي معد مسبقًا. هل الأسلوب الواثق يكفي لقبوله؟ حدد طريقة للتحقق.","explain":"هلوسة الذكاء الاصطناعي، التحقق من المعلومات، مراجعة النصوص والصور، الاستخدام المسؤول. ينشئ المعلم مخطط عرض قصير حول المدن الذكية باستخدام الأداة وفق الكتاب، ثم يراجع النص والصور ويشرح احتمال الهلوسة.","example":"راجع فقرة مولدة افتراضية: حدد ادعاء يحتاج إلى مصدر، وجملة يمكن تحسين وضوحها. احتفظ بالنسخة الأولى والتحسين مع تعليل القرار.","task":"تنشئ كل مجموعة مخطط مقدمة وأفكار وخاتمة. تتحقق من ادعاءين بالكتاب أو مصادر يحددها المعلم، وتعدل المحتوى وتدوّن ما تم تصحيحه.","misconception":"النص أو الصورة المولدة صحيحة ومسموح استخدامها لأن الأداة أنتجتها.","repair":"تحقق من المعلومات، ووضح طبيعة المحتوى، وراجع الحقوق والسياق، ولا تدرج بيانات شخصية في الطلب.","game":"محررون ومدققون: تنشئ كل مجموعة مخطط مقدمة وأفكار وخاتمة. تتحقق من ادعاءين بالكتاب أو مصادر يحددها المعلم، وتعدل المحتوى وتدوّن ما تم تصحيحه.","evidence":"أفحص سجل التوجيه الأول والمحسن، وصحة المعلومة ومصدر تحققها، ووضوح التعديل، ومسؤولية استخدام الصور. النتيجة المولدة وحدها لا تدل على تعلم الطالب.","question":"فسر هلوسة الذكاء الاصطناعي، واذكر خطوة تحقق، ثم قدم مثالًا على تعديل مسؤول في المحتوى.","answer":"قد تنشئ الأداة معلومات تبدو مقنعة لكنها غير صحيحة؛ نراجعها بمصدر موثوق ونصححها قبل الاستخدام ونراعي نسب المحتوى وخصوصية البيانات.","steps":[["5 دقائق","تحدي البداية","استرجاع عناصر التوجيه الواضح وربطها بجودة المحتوى."],["10 دقائق","نموذج عملي","هلوسة الذكاء الاصطناعي، التحقق من المعلومات، مراجعة النصوص والصور، الاستخدام المسؤول. ينشئ المعلم مخطط عرض قصير حول المدن الذكية باستخدام الأداة وفق الكتاب، ثم يراجع النص والصور ويشرح احتمال الهلوسة. مثال محلل: راجع فقرة مولدة افتراضية: حدد ادعاء يحتاج إلى مصدر، وجملة يمكن تحسين وضوحها. احتفظ بالنسخة الأولى والتحسين مع تعليل القرار."],["15 دقيقة","محررون ومدققون","تنشئ كل مجموعة مخطط مقدمة وأفكار وخاتمة. تتحقق من ادعاءين بالكتاب أو مصادر يحددها المعلم، وتعدل المحتوى وتدوّن ما تم تصحيحه."],["5 دقائق","قرار مسؤول","تناقش المجموعات حقوق النصوص والصور والخصوصية، وتوضح كيف نسبت مساعدة الأداة ولماذا لا تنقل الناتج دون مراجعة."],["5 دقائق","غلق فردي","يشرح الطالب الهلوسة وخطوة تحقق وتعديلًا أدخله؛ تستخدم النتائج للدعم."]]}],"goalBinding":"official","parentNote":"اكتب توجيهًا أوليًا ثم حسنه على الورق، مع توضيح التغيير."}]},{"id":"g7-u1-l3","title":"تأثير التقنية على البيئة والصحة","noorTitle":"تأثير التقنية على البيئة والصحة","officialPeriods":2,"source":"دليل المعلم ص44–47","goalSource":"noor-observed","quiz":[{"question":"جهاز قديم يعمل بصورة جيدة: القرار الأنسب غالبًا…","options":["رميه مع النفايات","إعادة استخدامه","تفكيكه دون إشراف"],"answer":1,"explanation":"إطالة عمر الجهاز وإصلاحه، إعادة استخدامه، وتدويره عبر الجهة المختصة. مثال توفير الطاقة: استخدام إعدادات السكون المناسبة وإيقاف الاستخدام غير الضروري."},{"question":"قبل مشاركة محتوى قد يكون مزيفًا…","options":["أتحقق من المصدر","أنشره لأنه مثير","أعتمد على جودة الصورة فقط"],"answer":0,"explanation":"من أمثلة التحسين رفع الجهاز إلى مستوى مناسب وأخذ راحة وتنظيم وقت الاستخدام. قبل مشاركة المحتوى نتحقق من المصدر والسياق؛ قد يكون المحتوى مزيفًا."}],"meetings":[{"id":"g7-u1-l3-m1","part":"1/1","title":"النفايات الإلكترونية وتوفير الطاقة + الصحة والتوازن والمسؤولية الرقمية","periods":[{"title":"النفايات الإلكترونية وتوفير الطاقة","outcomes":[{"id":"31905","text":"التعرف إلى مفهوم النفايات الإلكترونية وتأثيرها على البيئة."},{"id":"31906","text":"اقتراح حلول للحد من النفايات الإلكترونية."},{"id":"31907","text":"استخدام تقنيات توفير الطاقة."}],"reinforcement":false,"warm":"اعرض صورة جهاز قديم متعطل وجهاز قديم يعمل. هل نتخلص منهما بالطريقة نفسها؟ يبرر الطلبة اختياراتهم.","explain":"النفايات الإلكترونية، إعادة الاستخدام، إعادة التدوير، توفير الطاقة. يوضح المعلم مفهوم النفايات الإلكترونية وآثارها وطرق تقليلها؛ يميز الطلبة بينها وبين حذف الملفات.","example":"يراجع الفريق أجهزة افتراضية: جهاز صالح يحتاج صيانة، وآخر يمكن إعادة استخدامه، وآخر يحتاج جهة مختصة. يبرر القرار دون تفكيك أجهزة المدرسة.","task":"تختار المجموعات حلًا لكل موقف: إصلاح، إعادة استخدام، تبرع مناسب، أو تدوير مسؤول. يناقشون سبب القرار وتقنيات توفير الطاقة الواردة في الكتاب.","misconception":"حذف الملفات القديمة يعالج مشكلة النفايات الإلكترونية.","repair":"ميز بين بيانات مخزنة وجهاز مادي انتهى استخدامه. ناقش إطالة عمر الجهاز وإعادة الاستخدام والتعامل المسؤول مع المكونات.","game":"مجلس الحلول: تختار المجموعات حلًا لكل موقف: إصلاح، إعادة استخدام، تبرع مناسب، أو تدوير مسؤول. يناقشون سبب القرار وتقنيات توفير الطاقة الواردة في الكتاب.","evidence":"أتحقق من تصنيف الأجهزة وربط الحل بالحالة، ومن تفسير أثر تقليل الاستبدال غير الضروري وإصلاح الأجهزة وتدويرها.","question":"اذكر ثلاثة إجراءات تحد من النفايات الإلكترونية، وسلوكًا واحدًا يوفر الطاقة.","answer":"إطالة عمر الجهاز وإصلاحه، إعادة استخدامه، وتدويره عبر الجهة المختصة. مثال توفير الطاقة: استخدام إعدادات السكون المناسبة وإيقاف الاستخدام غير الضروري.","steps":[["5 دقائق","موقف مشكلة","يحدد الطلبة أجهزة قد تصبح نفايات إلكترونية وآثار التخلص غير المسؤول منها."],["10 دقائق","اكتشف البدائل","النفايات الإلكترونية، إعادة الاستخدام، إعادة التدوير، توفير الطاقة. يوضح المعلم مفهوم النفايات الإلكترونية وآثارها وطرق تقليلها؛ يميز الطلبة بينها وبين حذف الملفات. مثال محلل: يراجع الفريق أجهزة افتراضية: جهاز صالح يحتاج صيانة، وآخر يمكن إعادة استخدامه، وآخر يحتاج جهة مختصة. يبرر القرار دون تفكيك أجهزة المدرسة."],["15 دقيقة","مجلس الحلول","تختار المجموعات حلًا لكل موقف: إصلاح، إعادة استخدام، تبرع مناسب، أو تدوير مسؤول. يناقشون سبب القرار وتقنيات توفير الطاقة الواردة في الكتاب."],["5 دقائق","تطبيق","يعرض المعلم إعدادات توفير الطاقة المناسبة للأجهزة المتاحة، ويحدد الطلبة سلوكًا يخفف الاستهلاك."],["5 دقائق","تقويم","يكتب الطالب ثلاثة إجراءات ويشرح أثر أحدها في حماية البيئة."]]},{"title":"الصحة والتوازن والمسؤولية الرقمية","outcomes":[{"id":"31908","text":"التعرف إلى تأثير التقنية في الصحة."},{"id":"31909","text":"اتباع الممارسات الصحية عند استخدام الأجهزة الإلكترونية."},{"id":"31910","text":"توضيح آثار الإفراط في استخدام التقنية."},{"id":"31911","text":"اقتراح حلول للحد من الآثار البيئية والصحية للتقنية."}],"reinforcement":false,"warm":"صف وضعيتين أمام الحاسوب واطلب تحديد العادات الأفضل. يناقش الطلبة أهمية الراحة والتوازن دون مشاركة معلومات شخصية حساسة.","explain":"بيئة العمل المريحة، إجهاد العين، التوازن في الاستخدام، التزييف العميق. ينمذج المعلم الجلسة الملائمة وتنظيم الشاشة وفترات الراحة وفق الكتاب؛ يتدرب الطلبة على تنظيم مكان العمل.","example":"صمم بطاقة عادات استخدام: تنظيم الوقت وبيئة العمل والاستراحة والتوازن مع الأنشطة الأخرى، ثم اختر عادة قابلة للتطبيق والمراجعة.","task":"تحلل المجموعات مواقف الإفراط في الشاشات وتأخر النوم وقلة التواصل ومحتوى مزيف. تقدم حلولًا واقعية وتشرح أهمية التحقق قبل المشاركة.","misconception":"الاستراحة أو تعديل وضعية الاستخدام موضوع منفصل عن التعلم بالتقنية.","repair":"اربط عادات الاستخدام المتوازنة بالتركيز والراحة، وراجع إرشادات الكتاب دون تقديم تشخيص صحي للطالب.","game":"حل مواقف: تحلل المجموعات مواقف الإفراط في الشاشات وتأخر النوم وقلة التواصل ومحتوى مزيف. تقدم حلولًا واقعية وتشرح أهمية التحقق قبل المشاركة.","evidence":"ألاحظ تنظيم مكان العمل والتبرير. أقيم الحل على مناسبته للموقف وقابليته للتطبيق، وأصحح الاعتقاد أن المظهر الواقعي للمحتوى يعني صحته.","question":"حدد عادة قد تسبب إجهادًا، واقترح تحسينين. كيف تتصرف قبل مشاركة فيديو يبدو مثيرًا؟","answer":"من أمثلة التحسين رفع الجهاز إلى مستوى مناسب وأخذ راحة وتنظيم وقت الاستخدام. قبل مشاركة المحتوى نتحقق من المصدر والسياق؛ قد يكون المحتوى مزيفًا.","steps":[["5 دقائق","لاحظ","يحدد الطلبة أخطاء في وضعية جلوس نموذجية وصورة بيئة عمل."],["10 دقائق","تعلم ومارس","بيئة العمل المريحة، إجهاد العين، التوازن في الاستخدام، التزييف العميق. ينمذج المعلم الجلسة الملائمة وتنظيم الشاشة وفترات الراحة وفق الكتاب؛ يتدرب الطلبة على تنظيم مكان العمل. مثال محلل: صمم بطاقة عادات استخدام: تنظيم الوقت وبيئة العمل والاستراحة والتوازن مع الأنشطة الأخرى، ثم اختر عادة قابلة للتطبيق والمراجعة."],["15 دقيقة","حل مواقف","تحلل المجموعات مواقف الإفراط في الشاشات وتأخر النوم وقلة التواصل ومحتوى مزيف. تقدم حلولًا واقعية وتشرح أهمية التحقق قبل المشاركة."],["5 دقائق","خطة توازن","يضع كل طالب تحسينين في عاداته اليومية، ويناقش مع زميل مدى إمكانية تطبيقهما."],["5 دقائق","غلق","بطاقة خروج تحدد أثرًا جسديًا أو نفسيًا أو اجتماعيًا وسلوكًا يحد منه."]]}],"goalBinding":"official","parentNote":"راقب استخدام جهاز في المنزل واقترح طريقة لإطالة عمره أو تقليل استهلاكه، دون فتحه أو تفكيكه."}]},{"id":"g7-u1-l4","title":"المشروع","noorTitle":"المشروع","officialPeriods":2,"source":"دليل المعلم ص50–51","goalSource":"noor-observed","quiz":[{"question":"أداة الذكاء الاصطناعي في المشروع…","options":["تغني عن مراجعة المجموعة","تدعم العمل مع التحقق والمراجعة","تحل محل جميع الأدوار"],"answer":1,"explanation":"معيار النجاح: ترابط الموضوع والمخطط، سجل واضح للتوجيه والمراجعة، أدوار موزعة، وقرار تحسين قابل للتنفيذ."},{"question":"أفضل دليل على تعلم المجموعة…","options":["جمال الشرائح وحده","شرح القرارات والتحقق ومساهمة الأعضاء","نسخ الناتج المولد كما هو"],"answer":1,"explanation":"تقويم المشروع: دقة المحتوى، تنظيم الأفكار، وضوح العرض، تحقق موثق، استخدام مسؤول، ومشاركة فعلية. تُستخدم التغذية الراجعة للتحسين لا للمقارنة الشخصية."}],"meetings":[{"id":"g7-u1-l4-m1","part":"1/1","title":"المشروع: التخطيط وبناء المسودة + المشروع: العرض والتقييم والتأمل","periods":[{"title":"المشروع: التخطيط وبناء المسودة","outcomes":[{"id":"31935","text":"إنشاء محتوى عرض تقديمي باستخدام الذكاء الاصطناعي التوليدي مع مراعاة المسؤولية في استخدام النصوص والصور."}],"reinforcement":false,"warm":"اعرض الموضوعات التي حددها الدليل: أجيال الحاسوب، التقنيات الناشئة، الأثر البيئي والصحي، والاستخدام الأخلاقي للذكاء الاصطناعي. تختار المجموعة موضوعًا وتبرر أهميته.","explain":"اختيار الموضوع، توزيع الأدوار، مخطط العرض، سجل التوجيه والتحقق. تختار المجموعات الموضوع وتوزع أدوار البحث والتوجيه والمراجعة والتصميم؛ تبني مخطط مقدمة وأفكار رئيسة وخاتمة.","example":"تخطط المجموعة رسالة العرض والجمهور والمصادر، وتوزع الأدوار ثم تنشئ مسودة. لا يعتبر الناتج النهائي قبل فحص المعلومات وتوثيق المصدر.","task":"تستخدم المجموعات الأداة وفق ترتيبات المدرسة أو نتائج يعرضها المعلم. تحتفظ بالتوجيهات ومصادر التحقق، وتراجع النص والصور وتجهز مسودة منظمة.","misconception":"جمع نصوص الأداة دون مراجعة يعد مشروعًا مكتملًا.","repair":"ضع معايير للمحتوى والمصادر والوضوح والمساهمة؛ اطلب تفسير دور الأداة وما راجعه الطالب بنفسه.","game":"أنشئ وراجع: تستخدم المجموعات الأداة وفق ترتيبات المدرسة أو نتائج يعرضها المعلم. تحتفظ بالتوجيهات ومصادر التحقق، وتراجع النص والصور وتجهز مسودة منظمة.","evidence":"أتابع إسهام كل طالب وسجل الأدوار، وأراجع مخطط العرض ومصدر تحقق واحد على الأقل لكل مجموعة. أقدم التغذية الراجعة قبل التصميم النهائي.","question":"سلم مخططًا بمقدمة وأفكار وخاتمة، وتوجيهًا مستخدمًا، ومعلومة تحققت منها، وتحسينًا ستنفذه.","answer":"معيار النجاح: ترابط الموضوع والمخطط، سجل واضح للتوجيه والمراجعة، أدوار موزعة، وقرار تحسين قابل للتنفيذ.","steps":[["5 دقائق","إطلاق المشروع","يعرض المعلم المنتج المطلوب ومعايير النجاح: الدقة والتنظيم والمراجعة والمسؤولية والعمل الجماعي."],["10 دقائق","خطط","اختيار الموضوع، توزيع الأدوار، مخطط العرض، سجل التوجيه والتحقق. تختار المجموعات الموضوع وتوزع أدوار البحث والتوجيه والمراجعة والتصميم؛ تبني مخطط مقدمة وأفكار رئيسة وخاتمة. مثال محلل: تخطط المجموعة رسالة العرض والجمهور والمصادر، وتوزع الأدوار ثم تنشئ مسودة. لا يعتبر الناتج النهائي قبل فحص المعلومات وتوثيق المصدر."],["15 دقيقة","أنشئ وراجع","تستخدم المجموعات الأداة وفق ترتيبات المدرسة أو نتائج يعرضها المعلم. تحتفظ بالتوجيهات ومصادر التحقق، وتراجع النص والصور وتجهز مسودة منظمة."],["5 دقائق","نقد الأقران","تبادل مسودات: نقطة قوة، سؤال عن الدقة، واقتراح للتحسين. يحدد المعلم فجوات العمل."],["5 دقائق","نقطة تحقق","تسلم المجموعة مخططها وسجل التحقق وتحدد تحسينًا للحصة التالية."]]},{"title":"المشروع: العرض والتقييم والتأمل","outcomes":[{"id":"31935","text":"إنشاء محتوى عرض تقديمي باستخدام الذكاء الاصطناعي التوليدي مع مراعاة المسؤولية في استخدام النصوص والصور."}],"reinforcement":false,"warm":"تسترجع كل مجموعة التحسين الذي التزمت به، وتجهز دليلًا على تنفيذه قبل العرض.","explain":"عرض المشروع، التغذية الراجعة، التأمل، مخرجات التعلم. تعرض المجموعات نواتجها ضمن زمن موزع بحسب عدد المجموعات. يوضح الطلبة كيف استخدموا الأداة وكيف راجعوا المخرجات؛ يقدم الزملاء تعليقًا محددًا محترمًا.","example":"يقدم كل طالب قرارًا ساهم به، ودليلًا على صحته، وتحسينًا أجراه بعد المراجعة. لا ينوب مقرر المجموعة عن تعلم بقية أعضائها.","task":"يستخدم المعلم والطلبة معيار الدقة والتنظيم والعمل الجماعي والتحقق والمسؤولية؛ يكتب كل طالب مساهمته وما تعلمه.","misconception":"التقويم ينهي فرص تحسين المشروع.","repair":"استخدم التغذية الراجعة لتعديل محدد، وقارن النسختين وفق معيار واضح بدل الانطباع العام.","game":"قيم وتأمل: يستخدم المعلم والطلبة معيار الدقة والتنظيم والعمل الجماعي والتحقق والمسؤولية؛ يكتب كل طالب مساهمته وما تعلمه.","evidence":"أقيم توضيح خطوات العمل لا شكل العرض وحده. أسأل أفراد المجموعة عن مساهمتهم ومصدر تحققهم، وأقدم ملاحظة محددة قابلة للتحسين.","question":"ما دورك؟ كيف ساعدت الأداة؟ ما معلومة صححتها أو تحققت منها؟ كيف ستستخدم الذكاء الاصطناعي بمسؤولية في مشروع لاحق؟","answer":"تقويم المشروع: دقة المحتوى، تنظيم الأفكار، وضوح العرض، تحقق موثق، استخدام مسؤول، ومشاركة فعلية. تُستخدم التغذية الراجعة للتحسين لا للمقارنة الشخصية.","steps":[["5 دقائق","مراجعة أخيرة","تفحص المجموعات الدقة وتنظيم الشرائح وملاءمة الصور ونسب المساعدة والمصادر."],["25 دقيقة","معرض المشاريع","عرض المشروع، التغذية الراجعة، التأمل، مخرجات التعلم. تعرض المجموعات نواتجها ضمن زمن موزع بحسب عدد المجموعات. يوضح الطلبة كيف استخدموا الأداة وكيف راجعوا المخرجات؛ يقدم الزملاء تعليقًا محددًا محترمًا. مثال محلل: يقدم كل طالب قرارًا ساهم به، ودليلًا على صحته، وتحسينًا أجراه بعد المراجعة. لا ينوب مقرر المجموعة عن تعلم بقية أعضائها."],["5 دقائق","قيم وتأمل","يستخدم المعلم والطلبة معيار الدقة والتنظيم والعمل الجماعي والتحقق والمسؤولية؛ يكتب كل طالب مساهمته وما تعلمه."],["5 دقائق","احتفاء ونقل تعلم","يحتفي المعلم بالإنجازات ثم يوجه الطلبة إلى صفحات برامج أخرى ومخرجات التعلم، ويحدد مهارة تحتاج ممارسة لاحقة."]]}],"goalBinding":"review","parentNote":"استكمال المعلومات والصور المناسبة للمسودة مع مراجعتها، وفق ترتيبات الوصول المعتمدة من المعلم."}]}]},{"id":"g7-u2","title":"الرسوم المعلوماتية وتحرير الصور","noorTitle":"الرسوم المعلوماتية وتحرير الصور","number":2,"officialPeriods":11,"source":"دليل المعلم للسابع — الفصل الأول، ص56–75","lessons":[{"id":"g7-u2-l1","title":"مقدمة في تصميم الرسوم المعلوماتية","noorTitle":"مقدمة في تصميم الرسوم المعلوماتية","officialPeriods":3,"source":"دليل المعلم ص56–63","goalSource":"noor-observed","quiz":[{"question":"عرض أحداث مرتبة بحسب تواريخها","options":["مخطط زمني","مخطط مقارنة","مخطط عملية"],"answer":0,"explanation":"العلاقة هنا زمنية؛ يوضح الترتيب متى وقعت الأحداث."},{"question":"شرح خطوات إرسال واجب","options":["مخطط خريطة","مخطط عملية","مخطط مقارنة"],"answer":1,"explanation":"المطلوب إجراء بخطوات متسلسلة، لا مقارنة أو مواقع."},{"question":"اختيار عنصر بصري للتصميم","options":["عنصر يخدم الرسالة","أكثر عنصر زخرفة","أي صورة جميلة"],"answer":0,"explanation":"نربط العنصر بالمعلومة والجمهور، لا بالجمال وحده."},{"question":"صورة تغطي النص في القالب؛ ما الخطوة المناسبة؟","options":["تغيير الموضوع كله","إعادة ترتيب الصورة أو تغيير حجمها","إضافة صور أخرى"],"answer":1,"explanation":"تعالج المشكلة في موضع العنصر وحجمه قبل زيادة الازدحام."},{"question":"كيف تقدم ملاحظة مفيدة لزميل؟","options":["قل جميل فقط","اختر لونك المفضل","صف المشكلة واقترح إجراء محددًا"],"answer":2,"explanation":"المراجعة مرتبطة بمعيار واضح وخطوة قابلة للتنفيذ."},{"question":"متى تفتح النسخة المصدرة؟","options":["بعد التصدير للتحقق من الناتج","لا حاجة لفتحها","قبل جمع المحتوى فقط"],"answer":0,"explanation":"قد يظهر اختلاف في الملف النهائي؛ نتحقق من القراءة والمحتوى."}],"meetings":[{"id":"g7-u2-l1-m1","part":"1/2","title":"مقدمة في تصميم الرسوم المعلوماتية · لقاء 1/2","periods":[{"title":"رسالة بصرية يفهمها القارئ","outcomes":[{"id":"31936","text":"التعرف إلى مفهوم الرسوم المعلوماتية والهدف منها."},{"id":"31937","text":"التعرف إلى خصائص الرسوم المعلوماتية الفعّالة."}],"reinforcement":false,"warm":"اعرض مرفقي image_1 وimage_2 من الكتاب. امنح الطلبة 20 ثانية لاستخلاص الرسالة؛ هل كان العنوان أم الصورة أم ترتيب الأقسام سبب الفهم؟","explain":"الرسم المعلوماتي يجمع نصًا موجزًا وعناصر مرئية لشرح معلومات أو بيانات. الجاذبية ليست غاية منفصلة؛ نجاح التصميم أن يعرف القارئ الرسالة ويفهم العلاقة بين العناصر. نبدأ بتحديد الجمهور والهدف، ثم ننظم العنوان والأقسام ونختار عناصر تخدم الفكرة.","example":"ملصق يكتب «احم حسابك» ثم يضع ثلاث نصائح قصيرة مع رموز مناسبة أوضح من فقرة طويلة وسط صور لا ترتبط بالنص. اطلب تحديد وظيفة كل عنصر، ثم إزالة عنصر لا يؤدي وظيفة.","task":"حول فقرة قصيرة من مرفق المواطنة الرقمية إلى عنوان وثلاث أفكار ورمز مقترح لكل فكرة. اشرح كيف يساعد كل رمز على فهم النص.","misconception":"كثرة الزينة تعني جودة الرسم المعلوماتي.","repair":"قارن تصميمين بالمحتوى نفسه، أحدهما مزدحم والآخر منظم. اختر بناء على سهولة العثور على الرسالة، لا عدد الألوان.","game":"محقق التصميم: ابحث مع زميلك عن دليل للوضوح ودليل للازدحام، ثم اتفقا على تعديل واحد.","evidence":"يحدد الرسالة والجمهور ويبرر حذف عنصر زائد.","question":"هل كل صورة جميلة تخدم الفكرة؟","answer":"لا؛ يجب ربط اختيار العنصر بالرسالة والجمهور.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","اعرض مرفقي image_1 وimage_2 من الكتاب. امنح الطلبة 20 ثانية لاستخلاص الرسالة؛ هل كان العنوان أم الصورة أم ترتيب الأقسام سبب الفهم؟"],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","الرسم المعلوماتي يجمع نصًا موجزًا وعناصر مرئية لشرح معلومات أو بيانات. الجاذبية ليست غاية منفصلة؛ نجاح التصميم أن يعرف القارئ الرسالة ويفهم العلاقة بين العناصر. نبدأ بتحديد الجمهور والهدف، ثم ننظم العنوان والأقسام ونختار عناصر تخدم الفكرة. مثال المعلم: ملصق يكتب «احم حسابك» ثم يضع ثلاث نصائح قصيرة مع رموز مناسبة أوضح من فقرة طويلة وسط صور لا ترتبط بالنص. اطلب تحديد وظيفة كل عنصر، ثم إزالة عنصر لا يؤدي وظيفة."],["15 دقائق","الحصة 1 · تطبيق وتعاون","حول فقرة قصيرة من مرفق المواطنة الرقمية إلى عنوان وثلاث أفكار ورمز مقترح لكل فكرة. اشرح كيف يساعد كل رمز على فهم النص. النشاط التفاعلي المقترح: محقق التصميم: ابحث مع زميلك عن دليل للوضوح ودليل للازدحام، ثم اتفقا على تعديل واحد."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يحدد الرسالة والجمهور ويبرر حذف عنصر زائد. ويقدم تدخلًا عمليًا: قارن تصميمين بالمحتوى نفسه، أحدهما مزدحم والآخر منظم. اختر بناء على سهولة العثور على الرسالة، لا عدد الألوان."],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: هل كل صورة جميلة تخدم الفكرة؟ ثم يوثق خطوة تحسين."]]},{"title":"اختر النوع وارسم خطة","outcomes":[{"id":"31938","text":"التمييز بين أنواع الرسوم المعلوماتية وشرح الهدف من كل نوع."},{"id":"31939","text":"توضيح مراحل تصميم رسم معلوماتي."}],"reinforcement":false,"warm":"اعرض ثلاث مهام: ترتيب أحداث، مقارنة جهازين، شرح خطوات تسليم واجب. اطلب اختيار نوع الرسم قبل استخدام أي تطبيق.","explain":"المخطط الزمني يعرض أحداثًا وفق الزمن، ومخطط العملية يعرض خطوات متتابعة، ومخطط المقارنة يبرز أوجه التشابه والاختلاف. المخطط المعلوماتي ينظم نصائح أو معلومات قصيرة، ومخطط الخريطة أو الموقع يربط المعلومات بالأماكن. يتحدد الاختيار بطبيعة العلاقة في المعلومات.","example":"لتعليم تسليم الواجب نستخدم مخطط عملية بأسهم وخطوات، وللمقارنة بين جهازين نستخدم مخطط مقارنة بمعايير مشتركة. إذا كانت المهمة عرض أحداث تاريخية فالتسلسل الزمني أولى من قائمة غير مرتبة.","task":"صنف خمس بطاقات مواقف حسب النوع، ثم اختر موقفًا وارسم مخططه على الورق: الهدف، الجمهور، المعلومات، الترتيب، المراجعة.","misconception":"أي معلومات متتابعة هي مخطط زمني.","repair":"اسأل: هل الترتيب يعتمد على التاريخ أم على خطوات إجراء؟ أوضح الفرق باستخدام مثال واحد من كل نوع.","game":"بطاقات النوع المناسب: يمنح الفريق نقطة للتبرير الصحيح، لا للتسمية وحدها.","evidence":"يربط النوع بطبيعة المعلومات ويحدد خطوات التخطيط والمراجعة.","question":"أي نوع يناسب عرض مناطق في عمان وما يميز كل منطقة؟","answer":"مخطط الخريطة أو الموقع لأنه يربط البيانات بمكانها.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","اعرض ثلاث مهام: ترتيب أحداث، مقارنة جهازين، شرح خطوات تسليم واجب. اطلب اختيار نوع الرسم قبل استخدام أي تطبيق."],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","المخطط الزمني يعرض أحداثًا وفق الزمن، ومخطط العملية يعرض خطوات متتابعة، ومخطط المقارنة يبرز أوجه التشابه والاختلاف. المخطط المعلوماتي ينظم نصائح أو معلومات قصيرة، ومخطط الخريطة أو الموقع يربط المعلومات بالأماكن. يتحدد الاختيار بطبيعة العلاقة في المعلومات. مثال المعلم: لتعليم تسليم الواجب نستخدم مخطط عملية بأسهم وخطوات، وللمقارنة بين جهازين نستخدم مخطط مقارنة بمعايير مشتركة. إذا كانت المهمة عرض أحداث تاريخية فالتسلسل الزمني أولى من قائمة غير مرتبة."],["15 دقائق","الحصة 2 · تطبيق وتعاون","صنف خمس بطاقات مواقف حسب النوع، ثم اختر موقفًا وارسم مخططه على الورق: الهدف، الجمهور، المعلومات، الترتيب، المراجعة. النشاط التفاعلي المقترح: بطاقات النوع المناسب: يمنح الفريق نقطة للتبرير الصحيح، لا للتسمية وحدها."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يربط النوع بطبيعة المعلومات ويحدد خطوات التخطيط والمراجعة. ويقدم تدخلًا عمليًا: اسأل: هل الترتيب يعتمد على التاريخ أم على خطوات إجراء؟ أوضح الفرق باستخدام مثال واحد من كل نوع."],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: أي نوع يناسب عرض مناطق في عمان وما يميز كل منطقة؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"official","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."},{"id":"g7-u2-l1-m2","part":"2/2","title":"مقدمة في تصميم الرسوم المعلوماتية · لقاء 2/2","periods":[{"title":"من القالب إلى ملف قابل للمشاركة","outcomes":[{"id":"31940","text":"البحث عن قالب مناسب في تطبيق Canva (كانفا) لإنشاء رسم معلوماتي."},{"id":"31941","text":"حذف العناصر غير المرغوب فيها."},{"id":"31942","text":"إعادة ترتيب العناصر في التصميم."},{"id":"31943","text":"إضافة صورة وتغيير حجمها."},{"id":"31944","text":"تصدير تصاميم الرسم المعلوماتي بصيغ مختلفة."}],"reinforcement":false,"warm":"استرجع مخطط الحصة السابقة واسأل: ما الذي نحتفظ به عند تغيير القالب؟ الرسالة أم الزخرفة؟","explain":"القالب نقطة بداية قابلة للتعديل. نبحث عن قالب يناسب الموضوع والجمهور، ثم نحذف العنصر الزائد ونرتب الباقي ونضيف صورة مناسبة ونضبط حجمها دون تشويه. نراجع النص والترتيب قبل التصدير؛ صيغة الناتج تتبع الغرض من المشاركة.","example":"طبق أمام الطلبة على مثال الكتاب عن السلامة على الإنترنت: حدد عنصرًا زائدًا، احذفه، انقل عنصرًا إلى موضع أوضح، وأضف صورة بحجم متوازن. اشرح سبب كل قرار أثناء التنفيذ بدل عرض سلسلة نقرات صامتة.","task":"نفذ تعديلًا على قالب الكتاب: حذف عنصر، إعادة ترتيب، إضافة صورة وتغيير حجمها، ثم تصدير نسخة ومراجعة فتحها. احتفظ بالتصميم القابل للتحرير.","misconception":"القالب الجاهز يمنع تعديل ترتيب العناصر.","repair":"دع الطالب يغير موضع عنصر ويربط التغيير بوضوح القراءة. قارن النتيجة قبل التعديل وبعده.","game":"سباق الجودة: قائمة من أربع مهارات؛ لا فوز بالسرعة وحدها، بل تنفيذ وتفسير.","evidence":"ينفذ المهارات الأربع ويختار صيغة مناسبة لغرض الملف.","question":"هل التصدير يغني عن مراجعة التصميم؟","answer":"لا؛ نراجع المعلومات والقراءة ثم نفتح الملف المصدر للتأكد من سلامته.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","استرجع مخطط الحصة السابقة واسأل: ما الذي نحتفظ به عند تغيير القالب؟ الرسالة أم الزخرفة؟"],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","القالب نقطة بداية قابلة للتعديل. نبحث عن قالب يناسب الموضوع والجمهور، ثم نحذف العنصر الزائد ونرتب الباقي ونضيف صورة مناسبة ونضبط حجمها دون تشويه. نراجع النص والترتيب قبل التصدير؛ صيغة الناتج تتبع الغرض من المشاركة. مثال المعلم: طبق أمام الطلبة على مثال الكتاب عن السلامة على الإنترنت: حدد عنصرًا زائدًا، احذفه، انقل عنصرًا إلى موضع أوضح، وأضف صورة بحجم متوازن. اشرح سبب كل قرار أثناء التنفيذ بدل عرض سلسلة نقرات صامتة."],["15 دقائق","الحصة 1 · تطبيق وتعاون","نفذ تعديلًا على قالب الكتاب: حذف عنصر، إعادة ترتيب، إضافة صورة وتغيير حجمها، ثم تصدير نسخة ومراجعة فتحها. احتفظ بالتصميم القابل للتحرير. النشاط التفاعلي المقترح: سباق الجودة: قائمة من أربع مهارات؛ لا فوز بالسرعة وحدها، بل تنفيذ وتفسير."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: ينفذ المهارات الأربع ويختار صيغة مناسبة لغرض الملف. ويقدم تدخلًا عمليًا: دع الطالب يغير موضع عنصر ويربط التغيير بوضوح القراءة. قارن النتيجة قبل التعديل وبعده."],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: هل التصدير يغني عن مراجعة التصميم؟ ثم يوثق خطوة تحسين."]]},{"title":"عيادة تصميم وتثبيت المهارات","outcomes":[{"id":"31937","text":"التعرف إلى خصائص الرسوم المعلوماتية الفعّالة."},{"id":"31940","text":"البحث عن قالب مناسب في تطبيق Canva (كانفا) لإنشاء رسم معلوماتي."},{"id":"31941","text":"حذف العناصر غير المرغوب فيها."},{"id":"31942","text":"إعادة ترتيب العناصر في التصميم."},{"id":"31943","text":"إضافة صورة وتغيير حجمها."},{"id":"31944","text":"تصدير تصاميم الرسم المعلوماتي بصيغ مختلفة."}],"reinforcement":true,"warm":"اعرض نماذج الطلبة دون ترتيبها من الأفضل للأسوأ. اطلب لكل نموذج نقطة قوة وخطوة تحسين محددة.","explain":"هذه الحصة مخصصة لتثبيت مهارات الدرس بعد حصصه الرسمية الثلاث. يراجع الطالب عمله باستخدام معيار واضح ثم يحسن النسخة. يتبادل الزملاء دور المصمم والمراجع؛ المراجعة تصف أثر التغيير ولا تكتفي بعبارة «جميل».","example":"تعليق مفيد: «العنوان واضح، لكن الصورة تغطي النص؛ صغرها وانقلها إلى جانب الفقرة». تعليق ضعيف: «غير الشكل». بين أن التغذية الراجعة الجيدة تقترح إجراء قابلًا للتنفيذ.","task":"طبق تعديلين استجابة لملاحظتين، ثم اكتب سجل قرار: المشكلة، التعديل، الأثر. افتح الملف المصدر وأثبت أن المحتوى مقروء.","misconception":"المراجعة هي تغيير الألوان فقط.","repair":"اربط كل تغيير بمشكلة في المعلومات أو القراءة أو التوازن. إذا لم يوجد سبب، لا تطلب تغييرًا شكليًا.","game":"بطاقة خبير: يختار الطالب مثالًا ويشرح قرارًا تصميميًا لزميل يحتاج إلى دعم.","evidence":"يظهر تحسنًا محددًا بين نسختين ويشرح سببه.","question":"كيف أعرف أن التعديل حسن التصميم؟","answer":"بالمقارنة وفق معيار واضح مثل القراءة أو صحة المعلومات، لا بتفضيل اللون وحده.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","اعرض نماذج الطلبة دون ترتيبها من الأفضل للأسوأ. اطلب لكل نموذج نقطة قوة وخطوة تحسين محددة."],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","هذه الحصة مخصصة لتثبيت مهارات الدرس بعد حصصه الرسمية الثلاث. يراجع الطالب عمله باستخدام معيار واضح ثم يحسن النسخة. يتبادل الزملاء دور المصمم والمراجع؛ المراجعة تصف أثر التغيير ولا تكتفي بعبارة «جميل». مثال المعلم: تعليق مفيد: «العنوان واضح، لكن الصورة تغطي النص؛ صغرها وانقلها إلى جانب الفقرة». تعليق ضعيف: «غير الشكل». بين أن التغذية الراجعة الجيدة تقترح إجراء قابلًا للتنفيذ."],["15 دقائق","الحصة 2 · تطبيق وتعاون","طبق تعديلين استجابة لملاحظتين، ثم اكتب سجل قرار: المشكلة، التعديل، الأثر. افتح الملف المصدر وأثبت أن المحتوى مقروء. النشاط التفاعلي المقترح: بطاقة خبير: يختار الطالب مثالًا ويشرح قرارًا تصميميًا لزميل يحتاج إلى دعم."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يظهر تحسنًا محددًا بين نسختين ويشرح سببه. ويقدم تدخلًا عمليًا: اربط كل تغيير بمشكلة في المعلومات أو القراءة أو التوازن. إذا لم يوجد سبب، لا تطلب تغييرًا شكليًا."],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: كيف أعرف أن التعديل حسن التصميم؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"official","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."}]},{"id":"g7-u2-l2","title":"إنشاء الرسوم المعلوماتية","noorTitle":"إنشاء الرسوم المعلوماتية","officialPeriods":2,"source":"دليل المعلم ص64–68","goalSource":"noor-observed","quiz":[{"question":"مستطيل يغطي العنوان؛ أي إجراء أولى؟","options":["تعديل ترتيب الطبقات","حذف العنوان","زيادة عدد الأيقونات"],"answer":0,"explanation":"المشكلة تراكب طبقات؛ نضع النص فوق العنصر المناسب."},{"question":"هل الشفافية هي ترتيب الطبقات؟","options":["نعم، لا فرق","لا؛ الشفافية تغير ظهور العنصر","تغير نص العنوان"],"answer":1,"explanation":"الترتيب يحدد أمام وخلف؛ الشفافية تحدد مقدار ظهور العنصر."},{"question":"ماذا تقرر قبل ملء صفحة فارغة؟","options":["كل الفلاتر الممكنة","أكبر عدد من الصور","الرسالة والجمهور وترتيب المحتوى"],"answer":2,"explanation":"الأدوات تخدم خطة واضحة، لا تحل محل تحديد الغرض."}],"meetings":[{"id":"g7-u2-l2-m1","part":"1/1","title":"إنشاء الرسوم المعلوماتية · لقاء 1/1","periods":[{"title":"صفحة فارغة ورسالة مرتبة","outcomes":[{"id":"31945","text":"استخدام قالب تصميم فارغًا لإنشاء رسم معلوماتي."},{"id":"31946","text":"تغيير لون الخلفية في الرسم المعلوماتي."},{"id":"31947","text":"إضافة وتعديل عناصر مختلفة في الرسم المعلوماتي."},{"id":"31948","text":"إضافة النصوص وتحريرها في الرسم المعلوماتي."}],"reinforcement":false,"warm":"قارن قالبًا جاهزًا بصفحة فارغة. ماذا يتعين عليك أن تقرر بنفسك في الصفحة الفارغة؟","explain":"نحدد حجم صفحة التصميم حسب الحاجة، ونختار خلفية تسمح بقراءة النص، ثم نضيف الأشكال والرسومات والأيقونات والنصوص. العنوان يبين الرسالة والعناوين الفرعية تنظم الأقسام. نقل النصوص من المصدر يتطلب فهمها وتلخيصها ومراجعتها، لا ازدحام الصفحة بنسخها كلها.","example":"باستخدام مرفق السلوك المسؤول على الإنترنت، حول المحتوى إلى ثلاثة أقسام: حماية البيانات، احترام الآخرين، والتحقق من المعلومات. ابدأ بالخلفية ثم أضف العنوان والأشكال والنصوص وفق خطوات الكتاب.","task":"ابدأ بتصميم فارغ وحدد لون الخلفية، وأضف ثلاثة عناصر مختلفة وثلاثة نصوص قصيرة. اشرح الفرق بين العنصر الذي يزين والعنصر الذي يوضح.","misconception":"زيادة النص تجعل التصميم أكثر إفادة دائمًا.","repair":"اطلب صياغة الفكرة نفسها في جملة قصيرة ثم اختبارها على زميل: هل فهم النص دون شرح إضافي؟","game":"تحدي ثلاث رسائل: اجعل زميلًا يستخرج أفكارك الثلاث خلال نصف دقيقة.","evidence":"ينشئ صفحة فارغة ويضيف عناصر ونصوصًا تخدم الرسالة.","question":"ماذا أختار أولًا: الأيقونات أم الرسالة؟","answer":"الرسالة والجمهور؛ بعدها تختار عناصر مناسبة.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","قارن قالبًا جاهزًا بصفحة فارغة. ماذا يتعين عليك أن تقرر بنفسك في الصفحة الفارغة؟"],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","نحدد حجم صفحة التصميم حسب الحاجة، ونختار خلفية تسمح بقراءة النص، ثم نضيف الأشكال والرسومات والأيقونات والنصوص. العنوان يبين الرسالة والعناوين الفرعية تنظم الأقسام. نقل النصوص من المصدر يتطلب فهمها وتلخيصها ومراجعتها، لا ازدحام الصفحة بنسخها كلها. مثال المعلم: باستخدام مرفق السلوك المسؤول على الإنترنت، حول المحتوى إلى ثلاثة أقسام: حماية البيانات، احترام الآخرين، والتحقق من المعلومات. ابدأ بالخلفية ثم أضف العنوان والأشكال والنصوص وفق خطوات الكتاب."],["15 دقائق","الحصة 1 · تطبيق وتعاون","ابدأ بتصميم فارغ وحدد لون الخلفية، وأضف ثلاثة عناصر مختلفة وثلاثة نصوص قصيرة. اشرح الفرق بين العنصر الذي يزين والعنصر الذي يوضح. النشاط التفاعلي المقترح: تحدي ثلاث رسائل: اجعل زميلًا يستخرج أفكارك الثلاث خلال نصف دقيقة."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: ينشئ صفحة فارغة ويضيف عناصر ونصوصًا تخدم الرسالة. ويقدم تدخلًا عمليًا: اطلب صياغة الفكرة نفسها في جملة قصيرة ثم اختبارها على زميل: هل فهم النص دون شرح إضافي؟"],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: ماذا أختار أولًا: الأيقونات أم الرسالة؟ ثم يوثق خطوة تحسين."]]},{"title":"الطبقات والشفافية والتصدير","outcomes":[{"id":"31949","text":"تنظيم عناصر الرسم المعلوماتي وترتيبها باستخدام الطبقات وأدوات الشفافية."},{"id":"31950","text":"تصدير الرسم المعلوماتي وحفظه بتنسيق مناسب."}],"reinforcement":false,"warm":"ضع شكلًا يغطي عنوانًا واسأل: هل يجب حذف العنوان أم تغيير ترتيب الطبقات؟","explain":"كل عنصر يمثل طبقة. ترتيب الطبقات يحدد ما يظهر أمام غيره؛ إرسال عنصر إلى الخلف يختلف عن خفضه طبقة واحدة. الشفافية تؤثر في ظهور العنصر ولا تقوم مقام ترتيب الطبقات. نستخدمها عند الحاجة مع إبقاء النص واضحًا، ثم نراجع التصميم ونحفظه ونصدره بصيغة مناسبة.","example":"إذا غطى مستطيل النص، أرسله خلف النص. إذا كان صورة خلفية تشتت القراءة، اضبط شفافيتها أو غير موضع النص مع مقارنة القراءة. لا تجعل النص نفسه باهتًا لمجرد إظهار الخلفية.","task":"أصلح تعارض طبقتين، ثم طبق شفافية مناسبة على عنصر واختبر القراءة، وأعد تسمية الملف وصدره. سجل قرارًا واحدًا مرتبطًا بالطبقات.","misconception":"الشفافية وترتيب الطبقات يؤديان الوظيفة نفسها.","repair":"استخدم العناصر نفسها: غير ترتيبها دون شفافية، ثم غير الشفافية دون ترتيب. اطلب وصف الفرق المرئي.","game":"مسرح الطبقات: يرفع فريق بطاقات «أمام/خلف/شفافية» لحل مواقف يطرحها المعلم.","evidence":"يعالج تراكبًا ويضبط شفافية ويحفظ نسخة مناسبة.","question":"لماذا أحتفظ بنسخة قابلة للتحرير بعد التصدير؟","answer":"حتى أستطيع تعديل النص والعناصر دون البدء من جديد.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","ضع شكلًا يغطي عنوانًا واسأل: هل يجب حذف العنوان أم تغيير ترتيب الطبقات؟"],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","كل عنصر يمثل طبقة. ترتيب الطبقات يحدد ما يظهر أمام غيره؛ إرسال عنصر إلى الخلف يختلف عن خفضه طبقة واحدة. الشفافية تؤثر في ظهور العنصر ولا تقوم مقام ترتيب الطبقات. نستخدمها عند الحاجة مع إبقاء النص واضحًا، ثم نراجع التصميم ونحفظه ونصدره بصيغة مناسبة. مثال المعلم: إذا غطى مستطيل النص، أرسله خلف النص. إذا كان صورة خلفية تشتت القراءة، اضبط شفافيتها أو غير موضع النص مع مقارنة القراءة. لا تجعل النص نفسه باهتًا لمجرد إظهار الخلفية."],["15 دقائق","الحصة 2 · تطبيق وتعاون","أصلح تعارض طبقتين، ثم طبق شفافية مناسبة على عنصر واختبر القراءة، وأعد تسمية الملف وصدره. سجل قرارًا واحدًا مرتبطًا بالطبقات. النشاط التفاعلي المقترح: مسرح الطبقات: يرفع فريق بطاقات «أمام/خلف/شفافية» لحل مواقف يطرحها المعلم."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يعالج تراكبًا ويضبط شفافية ويحفظ نسخة مناسبة. ويقدم تدخلًا عمليًا: استخدم العناصر نفسها: غير ترتيبها دون شفافية، ثم غير الشفافية دون ترتيب. اطلب وصف الفرق المرئي."],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: لماذا أحتفظ بنسخة قابلة للتحرير بعد التصدير؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"official","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."}]},{"id":"g7-u2-l3","title":"تحرير الصور باستخدام الذًّكاء الاصطناعي","noorTitle":"تحرير الصور باستخدام الذًّكاء الاصطناعي","officialPeriods":3,"source":"دليل المعلم ص69–73","goalSource":"noor-observed","quiz":[{"question":"صورة مائلة قليلًا","options":["تدوير","مولد الخلفيات","فلتر"],"answer":0,"explanation":"التدوير يساعد على تصحيح الإمالة؛ لا نحتاج لتغيير الخلفية."},{"question":"عنصر صغير غير مرغوب داخل الصورة","options":["مزيل الخلفيات","الممحاة السحرية","تصدير"],"answer":1,"explanation":"الممحاة تعالج العنصر المحدد، ومزيل الخلفية يفصل الموضوع عن خلفيته."},{"question":"أريد فصل الموضوع عن الخلفية","options":["فلتر","تدوير","مزيل الخلفيات"],"answer":2,"explanation":"نحدد الأداة من المشكلة والغرض، لا من ترتيبها في القائمة."},{"question":"زميل يزيد شدة الفلتر دائمًا؛ ما رأيك؟","options":["الأعلى أفضل دائمًا","راجع الأثر واختر قدرًا مناسبًا","استغن عن المراجعة"],"answer":1,"explanation":"المبالغة قد تفقد التفاصيل أو تجعل الصورة غير طبيعية."},{"question":"صورة مولدة تبدو واقعية؛ كيف تستخدمها؟","options":["أقدمها بوصفها توثيقًا حقيقيًا","أخفي مصدرها","أوضح طبيعتها ولا أقدمها كتسجيل حقيقي"],"answer":2,"explanation":"الجاذبية لا تعني الصدق؛ يجب تجنب تضليل القارئ."},{"question":"هل إتقان التحرير يعني تشغيل كل الأدوات؟","options":["لا؛ اختيار مناسب مع تفسير ومراجعة","نعم، كلها مطلوبة","المعيار هو السرعة فقط"],"answer":0,"explanation":"الأداة تُختار لحل مشكلة محددة؛ كثرة المؤثرات ليست دليل إتقان."}],"meetings":[{"id":"g7-u2-l3-m1","part":"1/2","title":"تحرير الصور باستخدام الذًّكاء الاصطناعي · لقاء 1/2","periods":[{"title":"تصحيح الإمالة وإزالة عنصر","outcomes":[{"id":"31951","text":"تعديل إمالة الصور باستخدام أدوات تطبيق Canva (كانفا)."},{"id":"31952","text":"إزالة العناصر غير المرغوب فيها من الصور باستخدام أداة Magic Eraser (الممحاة السحرية)."}],"reinforcement":false,"warm":"اعرض ملف image_1_start والصورة النهائية من مرفقات المعلم. اطلب وصف اختلاف محدد قبل الحديث عن الأداة.","explain":"نميز بين القص والتدوير: القص يغير الجزء المعروض، والتدوير يساعد في تعديل الإمالة. الممحاة السحرية تعالج عنصرًا غير مرغوب فيه داخل الصورة، وتحتاج إلى تحديد دقيق ومراجعة المناطق المحيطة. التعديل الجيد يحافظ على الموضوع والتوازن ويجنب حذف جزء مطلوب.","example":"بين أثر تدوير بسيط لتصحيح خط مائل، ثم كبّر منطقة قبل إزالة عنصر وحدد حجم الفرشاة المناسب. راجع الحواف والفراغ الناتج، وتراجع عن التعديل إذا تضرر الموضوع.","task":"على نسخة من صورة الكتاب، عدل الإمالة ثم حدد عنصرًا لإزالته واشرح سبب الاختيار. قارن قبل وبعد واحتفظ بالأصل.","misconception":"إزالة عنصر تعني إزالة الخلفية كلها.","repair":"حدد عنصرًا صغيرًا داخل الصورة وناقش اختلاف المهمة عن فصل الموضوع عن الخلفية.","game":"اختيار الأداة: قص أم تدوير أم ممحاة؟ يبرر الطالب الأداة من المشكلة لا من اسمها.","evidence":"يختار الأداة الصحيحة ويعرض مقارنة قبل وبعد دون إتلاف الأصل.","question":"لماذا نكبر الصورة عند التحديد الدقيق؟","answer":"لرؤية الحدود وضبط التحديد وتجنب حذف أجزاء مجاورة.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","اعرض ملف image_1_start والصورة النهائية من مرفقات المعلم. اطلب وصف اختلاف محدد قبل الحديث عن الأداة."],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","نميز بين القص والتدوير: القص يغير الجزء المعروض، والتدوير يساعد في تعديل الإمالة. الممحاة السحرية تعالج عنصرًا غير مرغوب فيه داخل الصورة، وتحتاج إلى تحديد دقيق ومراجعة المناطق المحيطة. التعديل الجيد يحافظ على الموضوع والتوازن ويجنب حذف جزء مطلوب. مثال المعلم: بين أثر تدوير بسيط لتصحيح خط مائل، ثم كبّر منطقة قبل إزالة عنصر وحدد حجم الفرشاة المناسب. راجع الحواف والفراغ الناتج، وتراجع عن التعديل إذا تضرر الموضوع."],["15 دقائق","الحصة 1 · تطبيق وتعاون","على نسخة من صورة الكتاب، عدل الإمالة ثم حدد عنصرًا لإزالته واشرح سبب الاختيار. قارن قبل وبعد واحتفظ بالأصل. النشاط التفاعلي المقترح: اختيار الأداة: قص أم تدوير أم ممحاة؟ يبرر الطالب الأداة من المشكلة لا من اسمها."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يختار الأداة الصحيحة ويعرض مقارنة قبل وبعد دون إتلاف الأصل. ويقدم تدخلًا عمليًا: حدد عنصرًا صغيرًا داخل الصورة وناقش اختلاف المهمة عن فصل الموضوع عن الخلفية."],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: لماذا نكبر الصورة عند التحديد الدقيق؟ ثم يوثق خطوة تحسين."]]},{"title":"إزالة الخلفية وبناء خلفية مناسبة","outcomes":[{"id":"31953","text":"إزالة خلفيات الصور باستخدام أداة Background Remover (مزيل الخلفيات)."},{"id":"31954","text":"إنشاء خلفيات جديدة للصور باستخدام Background Generator (مولد الخلفيات)."}],"reinforcement":false,"warm":"اعرض موضوعًا واحدًا مع خلفيتين مختلفتين. كيف تغير الخلفية إحساسنا بالصورة ورسالتها؟","explain":"مزيل الخلفيات يفصل الموضوع عن خلفيته. مولد الخلفيات ينشئ خلفية وفق وصف؛ نختار وصفًا يخدم الموضوع ونراجع واقعية الناتج وحواف الموضوع واتساقه. هذه الأدوات لا تعفي من اختيار مسؤول ولا تحول الصورة المعدلة إلى توثيق حقيقي لحدث.","example":"فكر بصوت مسموع: أريد خلفية بسيطة لا تزاحم المبنى الرئيسي. اكتب وصفًا يحدد الموضوع والإضاءة والطابع دون معلومات شخصية، ثم ناقش لماذا قد ترفض نتيجة غير مناسبة.","task":"أزل خلفية نسخة الصورة إن كانت الأداة متاحة، واقترح وصفين لخلفية، ثم اختر أحدهما مع تبرير. راجع حدود الموضوع واتساق الصورة.","misconception":"أي خلفية مولدة مناسبة لأنها جديدة.","repair":"قارن النتيجة بالغرض المحدد مسبقًا؛ الجديدة قد تكون مشتتة أو غير منسجمة.","game":"مصمم أم مدقق: فريق يقترح وصفًا وفريق يذكر معيارًا لقبول النتيجة أو رفضها.","evidence":"يميز وظيفة المزيل والمولد ويبرر اختيار خلفية.","question":"متى أرفض خلفية تبدو جميلة؟","answer":"إذا لم تخدم الموضوع أو سببت التباسًا أو أظهرت سياقًا مضللًا.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","اعرض موضوعًا واحدًا مع خلفيتين مختلفتين. كيف تغير الخلفية إحساسنا بالصورة ورسالتها؟"],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","مزيل الخلفيات يفصل الموضوع عن خلفيته. مولد الخلفيات ينشئ خلفية وفق وصف؛ نختار وصفًا يخدم الموضوع ونراجع واقعية الناتج وحواف الموضوع واتساقه. هذه الأدوات لا تعفي من اختيار مسؤول ولا تحول الصورة المعدلة إلى توثيق حقيقي لحدث. مثال المعلم: فكر بصوت مسموع: أريد خلفية بسيطة لا تزاحم المبنى الرئيسي. اكتب وصفًا يحدد الموضوع والإضاءة والطابع دون معلومات شخصية، ثم ناقش لماذا قد ترفض نتيجة غير مناسبة."],["15 دقائق","الحصة 2 · تطبيق وتعاون","أزل خلفية نسخة الصورة إن كانت الأداة متاحة، واقترح وصفين لخلفية، ثم اختر أحدهما مع تبرير. راجع حدود الموضوع واتساق الصورة. النشاط التفاعلي المقترح: مصمم أم مدقق: فريق يقترح وصفًا وفريق يذكر معيارًا لقبول النتيجة أو رفضها."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يميز وظيفة المزيل والمولد ويبرر اختيار خلفية. ويقدم تدخلًا عمليًا: قارن النتيجة بالغرض المحدد مسبقًا؛ الجديدة قد تكون مشتتة أو غير منسجمة."],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: متى أرفض خلفية تبدو جميلة؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"official","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."},{"id":"g7-u2-l3-m2","part":"2/2","title":"تحرير الصور باستخدام الذًّكاء الاصطناعي · لقاء 2/2","periods":[{"title":"الوضوح والفلاتر والاستخدام المسؤول","outcomes":[{"id":"31955","text":"تحسين وضوح الصور باستخدام أداة Adjust (الضبط)."},{"id":"31956","text":"إضافة فلتر إلى الصورة وتعديل كثافته لتحسين مظهرها."},{"id":"31929","text":"استخدام الصور المُولّدة بالذكاء الاصطناعي بشكل أخلاقي ومسؤول."}],"reinforcement":false,"warm":"اعرض صورة بتعديل متوازن وأخرى مبالغ فيها. اطلب وصف أثر التعديل قبل الحكم على جمال الصورة.","explain":"الضبط يساعد في تحسين وضوح الصورة، والفلاتر تغير طابعها ويمكن تعديل كثافتها. نستخدم قدرًا مناسبًا بدل افتراض أن زيادة الحدة أو شدة الفلتر أفضل دائمًا. المسؤولية تشمل إذن استخدام الصورة واحترام الملكية والتمييز بين صورة معدلة وتوثيق حدث.","example":"قارن مرشحًا بشدة منخفضة وعالية، واطلب وصف التفاصيل التي فُقدت. في ملصق عن معلم سياحي، لا تعرض صورة مولدة على أنها صورة توثيقية حقيقية؛ اذكر طبيعة التعديل أو استخدم مصدرًا مناسبًا.","task":"طبق ضبطًا ثم فلترًا بكثافة مناسبة وقدم مقارنة قبل وبعد، واكتب سطرًا يوضح مصدر الصورة وطبيعة تعديلها.","misconception":"كل تعديل بالذكاء الاصطناعي يجعل الصورة أكثر صدقًا.","repair":"افصل بين الجاذبية والصدق: قد تبدو الصورة أفضل لكنها تغير واقعًا أو سياقًا.","game":"محكمة الصورة: يقبل الفريق تعديلًا أو يطلب مراجعته مع سبب يتصل بالدقة والحقوق.","evidence":"يحسن الصورة باعتدال ويبين المصدر والتعديل.","question":"هل يجوز تقديم صورة مولدة بوصفها صورة حقيقية لمكان؟","answer":"لا؛ يجب توضيح طبيعتها وعدم استخدامها لإيهام القارئ بأنها توثيق واقعي.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","اعرض صورة بتعديل متوازن وأخرى مبالغ فيها. اطلب وصف أثر التعديل قبل الحكم على جمال الصورة."],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","الضبط يساعد في تحسين وضوح الصورة، والفلاتر تغير طابعها ويمكن تعديل كثافتها. نستخدم قدرًا مناسبًا بدل افتراض أن زيادة الحدة أو شدة الفلتر أفضل دائمًا. المسؤولية تشمل إذن استخدام الصورة واحترام الملكية والتمييز بين صورة معدلة وتوثيق حدث. مثال المعلم: قارن مرشحًا بشدة منخفضة وعالية، واطلب وصف التفاصيل التي فُقدت. في ملصق عن معلم سياحي، لا تعرض صورة مولدة على أنها صورة توثيقية حقيقية؛ اذكر طبيعة التعديل أو استخدم مصدرًا مناسبًا."],["15 دقائق","الحصة 1 · تطبيق وتعاون","طبق ضبطًا ثم فلترًا بكثافة مناسبة وقدم مقارنة قبل وبعد، واكتب سطرًا يوضح مصدر الصورة وطبيعة تعديلها. النشاط التفاعلي المقترح: محكمة الصورة: يقبل الفريق تعديلًا أو يطلب مراجعته مع سبب يتصل بالدقة والحقوق."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يحسن الصورة باعتدال ويبين المصدر والتعديل. ويقدم تدخلًا عمليًا: افصل بين الجاذبية والصدق: قد تبدو الصورة أفضل لكنها تغير واقعًا أو سياقًا."],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: هل يجوز تقديم صورة مولدة بوصفها صورة حقيقية لمكان؟ ثم يوثق خطوة تحسين."]]},{"title":"مختبر الصورة: تثبيت ومراجعة","outcomes":[{"id":"31951","text":"تعديل إمالة الصور باستخدام أدوات تطبيق Canva (كانفا)."},{"id":"31952","text":"إزالة العناصر غير المرغوب فيها من الصور باستخدام أداة Magic Eraser (الممحاة السحرية)."},{"id":"31953","text":"إزالة خلفيات الصور باستخدام أداة Background Remover (مزيل الخلفيات)."},{"id":"31954","text":"إنشاء خلفيات جديدة للصور باستخدام Background Generator (مولد الخلفيات)."},{"id":"31955","text":"تحسين وضوح الصور باستخدام أداة Adjust (الضبط)."},{"id":"31956","text":"إضافة فلتر إلى الصورة وتعديل كثافته لتحسين مظهرها."},{"id":"31929","text":"استخدام الصور المُولّدة بالذكاء الاصطناعي بشكل أخلاقي ومسؤول."}],"reinforcement":true,"warm":"ارجع إلى الصورة الأصلية واطلب اختيار ثلاثة قرارات تعديل تخدم غرضًا واحدًا، لا تشغيل كل الأدوات.","explain":"حصة تثبيت بعد الحصص الرسمية الثلاث: يخطط الطالب للتعديل ويختار أدوات مناسبة ويقارن نتيجة كل قرار قبل اعتماده. الجودة هي خدمة الغرض وحفظ الموضوع والحقوق، لا عدد المؤثرات. سجّل الأداة والسبب والأثر ليصبح العمل قابلًا للتفسير.","example":"إذا كانت الإمالة هي المشكلة الأساسية، عدلها أولًا ولا تبدأ بفلاتر قوية. إذا كانت الخلفية تشتت، عالجها مع مراجعة حواف الموضوع. لا تعدّل جزءًا دون سبب يخدم الرسالة.","task":"أنجز سجلًا بثلاث قرارات: المشكلة، الأداة، النتيجة. أرفق الأصل والنسخة المعدلة وراجع عمل زميل حسب قائمة واضحة.","misconception":"نجاح التطبيق هو استخدام جميع الأدوات.","repair":"قدم مهمة لا تحتاج إلا أداة واحدة، ثم قارنها بنتيجة استخدام أدوات كثيرة دون سبب.","game":"خبير التعديل: يشرح الطالب أداة لزميله، والآخر يختار متى لا يستخدمها.","evidence":"يختار أقل تعديل مناسب ويشرح قراراته ويحافظ على المصدر.","question":"ما الدليل على أنني أتقنت الأداة؟","answer":"تنفيذ مناسب مع تفسير وظيفتها وحدود استخدامها، لا مجرد معرفة موقع الزر.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","ارجع إلى الصورة الأصلية واطلب اختيار ثلاثة قرارات تعديل تخدم غرضًا واحدًا، لا تشغيل كل الأدوات."],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","حصة تثبيت بعد الحصص الرسمية الثلاث: يخطط الطالب للتعديل ويختار أدوات مناسبة ويقارن نتيجة كل قرار قبل اعتماده. الجودة هي خدمة الغرض وحفظ الموضوع والحقوق، لا عدد المؤثرات. سجّل الأداة والسبب والأثر ليصبح العمل قابلًا للتفسير. مثال المعلم: إذا كانت الإمالة هي المشكلة الأساسية، عدلها أولًا ولا تبدأ بفلاتر قوية. إذا كانت الخلفية تشتت، عالجها مع مراجعة حواف الموضوع. لا تعدّل جزءًا دون سبب يخدم الرسالة."],["15 دقائق","الحصة 2 · تطبيق وتعاون","أنجز سجلًا بثلاث قرارات: المشكلة، الأداة، النتيجة. أرفق الأصل والنسخة المعدلة وراجع عمل زميل حسب قائمة واضحة. النشاط التفاعلي المقترح: خبير التعديل: يشرح الطالب أداة لزميله، والآخر يختار متى لا يستخدمها."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يختار أقل تعديل مناسب ويشرح قراراته ويحافظ على المصدر. ويقدم تدخلًا عمليًا: قدم مهمة لا تحتاج إلا أداة واحدة، ثم قارنها بنتيجة استخدام أدوات كثيرة دون سبب."],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: ما الدليل على أنني أتقنت الأداة؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"official","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."}]},{"id":"g7-u2-l4","title":"المشروع","noorTitle":"المشروع","officialPeriods":3,"source":"دليل المعلم ص74–75","goalSource":"noor-observed","quiz":[{"question":"كيف تبدأ مشروع معلم سياحي عماني؟","options":["صور كثيرة ثم معلومات غير موثقة","موضوع ورسالة وجمهور ومصادر","الفلاتر فقط"],"answer":1,"explanation":"خطة المحتوى والمصادر توجه العمل وتمنع المعلومات المختلقة."},{"question":"الفريق ترك كل التنفيذ لطالب واحد؛ ما التحسين؟","options":["تبادل الأدوار وتوثيق المساهمة","إخفاء أسماء المشاركين","إلغاء المراجعة"],"answer":0,"explanation":"كل طالب يحتاج إلى مشاركة ودليل تعلم عملي."},{"question":"ما المراجعة التي تسبق النسخة النهائية؟","options":["لون الخلفية وحده","عدد الأشكال","المحتوى والقراءة والحقوق وتنظيم العناصر"],"answer":2,"explanation":"جودة المشروع تجمع دقة المعلومات والتصميم المسؤول والواضح."},{"question":"كيف يكون عرض المشروع مفيدًا؟","options":["قراءة كل النصوص فقط","رسالة ومصدر وقرار وتحسين","عرض المؤثرات فقط"],"answer":1,"explanation":"العرض يوضح التعلم والقرار والمصدر بدل إعادة ما يراه القارئ."},{"question":"ظهر أن مصدر صورة غير واضح؛ ما الإجراء؟","options":["تغيير لونها","إخفاء المشكلة","توثيق مناسب أو استبدال بمصدر مسموح"],"answer":2,"explanation":"تغيير اللون لا يعالج مسألة الحقوق أو المصدر."},{"question":"كيف تثبت أن النسخة الجديدة أفضل؟","options":["مقارنة وفق معيار واضح","ذكر أنها أحدث فقط","عدد المؤثرات"],"answer":0,"explanation":"الدليل يبين تحسن القراءة أو الدقة أو المسؤولية أو تنظيم العناصر."}],"meetings":[{"id":"g7-u2-l4-m1","part":"1/2","title":"المشروع · لقاء 1/2","periods":[{"title":"مشروع عمان: بحث ومخطط","outcomes":[{"id":"31936","text":"التعرف إلى مفهوم الرسوم المعلوماتية والهدف منها."},{"id":"31939","text":"توضيح مراحل تصميم رسم معلوماتي."},{"id":"31945","text":"استخدام قالب تصميم فارغًا لإنشاء رسم معلوماتي."}],"reinforcement":false,"warm":"اعرض مهمة الدليل: رسم معلوماتي عن معلم سياحي أو وجبة شعبية في سلطنة عمان. اسأل: ما الرسالة التي نريد أن يفهمها زائر المدرسة؟","explain":"نختار موضوعًا محددًا وجمهورًا ورسالة، ثم نجمع معلومات وصورًا من مصادر مناسبة ونقسم المحتوى إلى أقسام. يعمل الباحث والكاتب والمصمم والمدقق بأدوار متبادلة؛ مساهمة كل طالب واضحة. التخطيط قبل التصميم يمنع إعادة العمل بسبب محتوى غير منظم.","example":"موضوع مثل معلم سياحي يُعرض بعنوان واضح، ومعلومتين موثقتين، وصورة مناسبة، ونصيحة للزائر. لا تستخدم أرقامًا أو معلومات لم تتحقق منها؛ سجل المصدر أمام كل معلومة.","task":"سلم بطاقة مشروع: الموضوع والجمهور والرسالة، ثلاثة أقسام، مصادر المعلومات والصورة، توزيع الأدوار، ومخطط ورقي.","misconception":"يمكن جمع الصور ثم اختراع معلومات تملأ الفراغ.","repair":"اربط كل عنصر بمعلومة موثقة ورسالة، واترك معلومة غير مؤكدة خارج التصميم حتى تراجعها.","game":"سوق الأفكار: يعرض الفريق رسالته في نصف دقيقة، ويقترح فريق آخر سؤالًا واحدًا يجعلها أدق.","evidence":"يقدم مخططًا بمصادر وأدوار ورسالة محددة.","question":"لماذا نحدد الجمهور قبل الألوان؟","answer":"لأن الجمهور يؤثر في اللغة وكمية المعلومات وطريقة العرض.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","اعرض مهمة الدليل: رسم معلوماتي عن معلم سياحي أو وجبة شعبية في سلطنة عمان. اسأل: ما الرسالة التي نريد أن يفهمها زائر المدرسة؟"],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","نختار موضوعًا محددًا وجمهورًا ورسالة، ثم نجمع معلومات وصورًا من مصادر مناسبة ونقسم المحتوى إلى أقسام. يعمل الباحث والكاتب والمصمم والمدقق بأدوار متبادلة؛ مساهمة كل طالب واضحة. التخطيط قبل التصميم يمنع إعادة العمل بسبب محتوى غير منظم. مثال المعلم: موضوع مثل معلم سياحي يُعرض بعنوان واضح، ومعلومتين موثقتين، وصورة مناسبة، ونصيحة للزائر. لا تستخدم أرقامًا أو معلومات لم تتحقق منها؛ سجل المصدر أمام كل معلومة."],["15 دقائق","الحصة 1 · تطبيق وتعاون","سلم بطاقة مشروع: الموضوع والجمهور والرسالة، ثلاثة أقسام، مصادر المعلومات والصورة، توزيع الأدوار، ومخطط ورقي. النشاط التفاعلي المقترح: سوق الأفكار: يعرض الفريق رسالته في نصف دقيقة، ويقترح فريق آخر سؤالًا واحدًا يجعلها أدق."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يقدم مخططًا بمصادر وأدوار ورسالة محددة. ويقدم تدخلًا عمليًا: اربط كل عنصر بمعلومة موثقة ورسالة، واترك معلومة غير مؤكدة خارج التصميم حتى تراجعها."],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: لماذا نحدد الجمهور قبل الألوان؟ ثم يوثق خطوة تحسين."]]},{"title":"بناء النسخة الأولى ومراجعتها","outcomes":[{"id":"31946","text":"تغيير لون الخلفية في الرسم المعلوماتي."},{"id":"31947","text":"إضافة وتعديل عناصر مختلفة في الرسم المعلوماتي."},{"id":"31948","text":"إضافة النصوص وتحريرها في الرسم المعلوماتي."},{"id":"31949","text":"تنظيم عناصر الرسم المعلوماتي وترتيبها باستخدام الطبقات وأدوات الشفافية."}],"reinforcement":false,"warm":"راجع مخطط كل فريق: هل يعرف أي نص وأي صورة سيضع في كل قسم؟","explain":"نبني الرسم المعلوماتي ونرتب العنوان والعناوين الفرعية والعناصر، ونستخدم الخلفية والطبقات والشفافية لخدمة القراءة. تُراجع المعلومات والإملاء والحقوق أثناء العمل، لا بعد الانتهاء فقط. نسجل مشكلة واجهتنا وطريقة حلها لنعرض رحلة التعلم.","example":"ابدأ بالقسم الأول واعرض نسخة بسيطة قابلة للقراءة. قارن عنوانًا واضحًا بعنوان يضيع فوق صورة، ثم عدل موضعه أو طبقات الخلفية. اطلب من زميل غير مشارك استخلاص الرسالة.","task":"أنجز نسخة أولى، ثم اجمع ملاحظتين: واحدة عن المحتوى وأخرى عن التصميم، ونفذ تعديلًا قابلًا للتتبع.","misconception":"توزيع الأدوار يعني أن المصمم وحده يتعلم الأدوات.","repair":"بدل الأدوار خلال التنفيذ واطلب من كل طالب تفسير مهارة عملية نفذها.","game":"مراجع الخمس نقاط: الرسالة، المصدر، القراءة، التوازن، والحقوق.","evidence":"يوثق تعديلًا ويبرر قرارات تنظيم العناصر.","question":"ماذا يجعل تعليق زميلك مفيدًا؟","answer":"أن يصف مشكلة محددة ويقترح إجراء يمكن تنفيذه.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","راجع مخطط كل فريق: هل يعرف أي نص وأي صورة سيضع في كل قسم؟"],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","نبني الرسم المعلوماتي ونرتب العنوان والعناوين الفرعية والعناصر، ونستخدم الخلفية والطبقات والشفافية لخدمة القراءة. تُراجع المعلومات والإملاء والحقوق أثناء العمل، لا بعد الانتهاء فقط. نسجل مشكلة واجهتنا وطريقة حلها لنعرض رحلة التعلم. مثال المعلم: ابدأ بالقسم الأول واعرض نسخة بسيطة قابلة للقراءة. قارن عنوانًا واضحًا بعنوان يضيع فوق صورة، ثم عدل موضعه أو طبقات الخلفية. اطلب من زميل غير مشارك استخلاص الرسالة."],["15 دقائق","الحصة 2 · تطبيق وتعاون","أنجز نسخة أولى، ثم اجمع ملاحظتين: واحدة عن المحتوى وأخرى عن التصميم، ونفذ تعديلًا قابلًا للتتبع. النشاط التفاعلي المقترح: مراجع الخمس نقاط: الرسالة، المصدر، القراءة، التوازن، والحقوق."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يوثق تعديلًا ويبرر قرارات تنظيم العناصر. ويقدم تدخلًا عمليًا: بدل الأدوار خلال التنفيذ واطلب من كل طالب تفسير مهارة عملية نفذها."],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: ماذا يجعل تعليق زميلك مفيدًا؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"review","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."},{"id":"g7-u2-l4-m2","part":"2/2","title":"المشروع · لقاء 2/2","periods":[{"title":"التصدير والعرض والتقويم","outcomes":[{"id":"31950","text":"تصدير الرسم المعلوماتي وحفظه بتنسيق مناسب."},{"id":"31929","text":"استخدام الصور المُولّدة بالذكاء الاصطناعي بشكل أخلاقي ومسؤول."}],"reinforcement":false,"warm":"جهز معرضًا مصغرًا. قبل العرض، يفتح كل فريق النسخة المصدرة ويتأكد من القراءة والمحتوى.","explain":"تُراجع النسخة النهائية ثم تصدر بصيغة مناسبة. يعرض الفريق رسالته ومصدر معلومة وقرارًا تصميميًا وتحديًا وكيف حله. التقويم ينظر إلى دقة المعلومات والوضوح والمسؤولية والمشاركة، وليس مهارة المتحدث وحده.","example":"عرض قصير منظم: موضوعنا هو… جمهورنا… تحققنا من… غيرنا… لأن… نحتاج إلى تحسين… اطلب تعليقًا يحدد نقطة قوة وخطوة تالية لكل فريق.","task":"قدم الرسم النهائي وشرحًا قصيرًا، وسلم قائمة المصادر وسجل تعديل واحد ومساهمة كل عضو.","misconception":"العرض هو قراءة جميع النصوص على الملصق.","repair":"حدد زمنًا قصيرًا لشرح الفكرة والقرار والمصدر بدل إعادة قراءة ما يراه الجمهور.","game":"جولة المعرض: لكل زائر ملاحظة قوة وملاحظة تحسين، دون ترتيب الطلبة بحسب الجمال وحده.","evidence":"يعرض ملفًا سليمًا ويشرح المصدر والتحسين والمساهمة.","question":"ما الفرق بين ملف قابل للتحرير ونسخة مصدرة؟","answer":"الأول يتيح تعديل العناصر، والثانية معدة للمشاركة أو الطباعة بحسب الصيغة.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","جهز معرضًا مصغرًا. قبل العرض، يفتح كل فريق النسخة المصدرة ويتأكد من القراءة والمحتوى."],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","تُراجع النسخة النهائية ثم تصدر بصيغة مناسبة. يعرض الفريق رسالته ومصدر معلومة وقرارًا تصميميًا وتحديًا وكيف حله. التقويم ينظر إلى دقة المعلومات والوضوح والمسؤولية والمشاركة، وليس مهارة المتحدث وحده. مثال المعلم: عرض قصير منظم: موضوعنا هو… جمهورنا… تحققنا من… غيرنا… لأن… نحتاج إلى تحسين… اطلب تعليقًا يحدد نقطة قوة وخطوة تالية لكل فريق."],["15 دقائق","الحصة 1 · تطبيق وتعاون","قدم الرسم النهائي وشرحًا قصيرًا، وسلم قائمة المصادر وسجل تعديل واحد ومساهمة كل عضو. النشاط التفاعلي المقترح: جولة المعرض: لكل زائر ملاحظة قوة وملاحظة تحسين، دون ترتيب الطلبة بحسب الجمال وحده."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يعرض ملفًا سليمًا ويشرح المصدر والتحسين والمساهمة. ويقدم تدخلًا عمليًا: حدد زمنًا قصيرًا لشرح الفكرة والقرار والمصدر بدل إعادة قراءة ما يراه الجمهور."],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: ما الفرق بين ملف قابل للتحرير ونسخة مصدرة؟ ثم يوثق خطوة تحسين."]]},{"title":"تحسين المنتج وإغلاق الوحدة","outcomes":[{"id":"31937","text":"التعرف إلى خصائص الرسوم المعلوماتية الفعّالة."},{"id":"31949","text":"تنظيم عناصر الرسم المعلوماتي وترتيبها باستخدام الطبقات وأدوات الشفافية."},{"id":"31950","text":"تصدير الرسم المعلوماتي وحفظه بتنسيق مناسب."},{"id":"31929","text":"استخدام الصور المُولّدة بالذكاء الاصطناعي بشكل أخلاقي ومسؤول."}],"reinforcement":true,"warm":"اجمع الملاحظات واطلب لكل طالب تحديد مهارة أتقنها وأخرى يريد إعادة ممارستها.","explain":"حصة تثبيت بعد ثلاث حصص المشروع الرسمية: يُحسن الفريق المنتج استجابة للتقويم ثم يقارن النسختين. يعود الطالب إلى مخرجات التعلم ويقدم دليلًا من عمله على التقدم. اختتام الوحدة يدعم نقل مهارات الوضوح والدقة والمسؤولية إلى تصميمات أخرى.","example":"تعليق يقول «مصدر الصورة غير موضح» يؤدي إلى إضافة نسبة مناسبة أو استبدال الصورة بمصدر مسموح، ثم توثيق القرار. لا تعالج مشكلة الحقوق بتغيير اللون أو اقتصاص الاسم.","task":"نفذ تحسينًا في المعلومات وآخر في التصميم، ثم سلم مقارنة قبل وبعد وتأملًا: القرار الذي غير فهمي والدليل الذي أقدمه.","misconception":"التقويم الختامي ينهي فرص التحسين.","repair":"اجعل الملاحظة مدخلًا لتعديل محدد، ثم تحقق أن النسخة الجديدة عالجت السبب.","game":"وسام الدليل: يُمنح لتعليل تحسين واضح، أو تصحيح خطأ، أو دعم زميل، دون درجات رسمية تلقائية.","evidence":"يقارن نسختين ويبين تعلمه بعمل ملموس.","question":"كيف أنقل ما تعلمته إلى ملصق جديد؟","answer":"أبدأ بالرسالة والجمهور والمصدر، ثم أنظم عناصر تدعم الفهم وأراجع النتيجة.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","اجمع الملاحظات واطلب لكل طالب تحديد مهارة أتقنها وأخرى يريد إعادة ممارستها."],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","حصة تثبيت بعد ثلاث حصص المشروع الرسمية: يُحسن الفريق المنتج استجابة للتقويم ثم يقارن النسختين. يعود الطالب إلى مخرجات التعلم ويقدم دليلًا من عمله على التقدم. اختتام الوحدة يدعم نقل مهارات الوضوح والدقة والمسؤولية إلى تصميمات أخرى. مثال المعلم: تعليق يقول «مصدر الصورة غير موضح» يؤدي إلى إضافة نسبة مناسبة أو استبدال الصورة بمصدر مسموح، ثم توثيق القرار. لا تعالج مشكلة الحقوق بتغيير اللون أو اقتصاص الاسم."],["15 دقائق","الحصة 2 · تطبيق وتعاون","نفذ تحسينًا في المعلومات وآخر في التصميم، ثم سلم مقارنة قبل وبعد وتأملًا: القرار الذي غير فهمي والدليل الذي أقدمه. النشاط التفاعلي المقترح: وسام الدليل: يُمنح لتعليل تحسين واضح، أو تصحيح خطأ، أو دعم زميل، دون درجات رسمية تلقائية."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يقارن نسختين ويبين تعلمه بعمل ملموس. ويقدم تدخلًا عمليًا: اجعل الملاحظة مدخلًا لتعديل محدد، ثم تحقق أن النسخة الجديدة عالجت السبب."],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: كيف أنقل ما تعلمته إلى ملصق جديد؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"review","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."}]}]},{"id":"g7-u3","title":"الشبكات والمواطنة الرقمية","noorTitle":"الشبكات والمواطنة الرقمية","number":3,"officialPeriods":8,"source":"دليل المعلم للسابع — الفصل الأول، ص80–98","lessons":[{"id":"g7-u3-l1","title":"شبكات الحاسوب","noorTitle":"شبكات الحاسوب","officialPeriods":2,"source":"دليل المعلم ص80–85","goalSource":"teacher-guide","quiz":[{"question":"تعطل اتصال جهاز طرفي في الهيكلية النجمية؛ ما الأثر المعتاد؟","options":["تتوقف كل الأجهزة دائمًا","يتأثر الجهاز المتصل بهذه الوصلة","يتغير نموذج الشبكة"],"answer":1,"explanation":"تمييز موضع العطل أهم من حفظ اسم الهيكلية."},{"question":"وصلت الحزم بترتيب مختلف؛ كيف نبني الرسالة؟","options":["نستخدم أرقام الأجزاء لإعادة التجميع","نحذفها كلها","نتجاهل العناوين"],"answer":0,"explanation":"المحاكاة توضح أن ترتيب الوصول يمكن أن يختلف عن ترتيب المحتوى."},{"question":"ما الذي يصف دور الجهاز في تقديم الخدمة؟","options":["لون الكابل","الهيكلية وحدها","نموذج الشبكة"],"answer":2,"explanation":"الهيكلية تصف الربط، والنموذج يصف الأدوار."}],"meetings":[{"id":"g7-u3-l1-m1","part":"1/1","title":"شبكات الحاسوب · لقاء 1/1","periods":[{"title":"شبكة واحدة وهيكليات مختلفة","outcomes":[{"text":"التعرف إلى مفهوم شبكة الحاسوب."},{"text":"التعرف إلى مفهوم هيكلية الشبكة."},{"text":"التمييز بين أنواع هيكليات الشبكة."}],"reinforcement":false,"warm":"اعرض موقفًا: أربع مجموعات تريد استخدام طابعة واحدة. يكتب كل طالب اقتراحًا لمشاركة المورد، ثم يحدد ما الذي يحتاج إلى اتصال.","explain":"شبكة الحاسوب تربط أجهزة لتبادل البيانات ومشاركة الموارد. الهيكلية تصف طريقة اتصال الأجهزة؛ نقطة إلى نقطة تربط جهازين، والخطية تجعل الأجهزة تشترك في مسار رئيسي، والنجمية تصل كل جهاز بجهاز مركزي. تختلف الهيكليات في التوصيلات وتأثير الأعطال، وليس في شكل الرسم وحده.","example":"في الهيكلية النجمية، تعطل وصلة جهاز واحد يعزل ذلك الجهاز عادة؛ تعطل الجهاز المركزي يؤثر في الشبكة كلها. في الخطية، تؤثر مشكلة المسار الرئيسي في الاتصالات. ارسم الوضع قبل العطل وبعده وناقش السبب.","task":"ارسم ثلاث هيكليات لأجهزة افتراضية. لون موضع الاتصال ثم ضع بطاقة عطل واشرح الأجهزة المتأثرة. لا تفصل أي وصلات حقيقية في مختبر المدرسة.","misconception":"أي عطل في جهاز طرفي يوقف الشبكة النجمية كلها.","repair":"افصل على الرسم بين عطل الوصلة الطرفية وعطل الجهاز المركزي. اجعل الطالب يتتبع مسار جهازين آخرين.","game":"مهندس الشبكة: فريق يرسم، وفريق يختار بطاقة عطل، وثالث يتحقق من التفسير. تمنح النقطة للدليل الصحيح.","evidence":"يميز الهيكليات ويربط أثر العطل بموضعه، ويشرح موردًا يمكن مشاركته.","question":"هل الهيكلية هي طريقة توزيع الخدمات؟","answer":"لا؛ الهيكلية تصف الاتصال، أما النموذج فيصف الأدوار والخدمات.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","اعرض موقفًا: أربع مجموعات تريد استخدام طابعة واحدة. يكتب كل طالب اقتراحًا لمشاركة المورد، ثم يحدد ما الذي يحتاج إلى اتصال."],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","شبكة الحاسوب تربط أجهزة لتبادل البيانات ومشاركة الموارد. الهيكلية تصف طريقة اتصال الأجهزة؛ نقطة إلى نقطة تربط جهازين، والخطية تجعل الأجهزة تشترك في مسار رئيسي، والنجمية تصل كل جهاز بجهاز مركزي. تختلف الهيكليات في التوصيلات وتأثير الأعطال، وليس في شكل الرسم وحده. مثال المعلم: في الهيكلية النجمية، تعطل وصلة جهاز واحد يعزل ذلك الجهاز عادة؛ تعطل الجهاز المركزي يؤثر في الشبكة كلها. في الخطية، تؤثر مشكلة المسار الرئيسي في الاتصالات. ارسم الوضع قبل العطل وبعده وناقش السبب."],["15 دقائق","الحصة 1 · تطبيق وتعاون","ارسم ثلاث هيكليات لأجهزة افتراضية. لون موضع الاتصال ثم ضع بطاقة عطل واشرح الأجهزة المتأثرة. لا تفصل أي وصلات حقيقية في مختبر المدرسة. النشاط التفاعلي المقترح: مهندس الشبكة: فريق يرسم، وفريق يختار بطاقة عطل، وثالث يتحقق من التفسير. تمنح النقطة للدليل الصحيح."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يميز الهيكليات ويربط أثر العطل بموضعه، ويشرح موردًا يمكن مشاركته. ويقدم تدخلًا عمليًا: افصل على الرسم بين عطل الوصلة الطرفية وعطل الجهاز المركزي. اجعل الطالب يتتبع مسار جهازين آخرين."],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: هل الهيكلية هي طريقة توزيع الخدمات؟ ثم يوثق خطوة تحسين."]]},{"title":"أدوار الأجهزة ورحلة الحزمة","outcomes":[{"text":"شرح كيفية عمل نموذج النظير للنظير ونموذج العميل والمزوّد."},{"text":"شرح كيفية تبادل المعلومات عبر الشبكة."}],"reinforcement":false,"warm":"اسأل: إذا اتصلت أجهزة الصف بالطريقة نفسها، هل يلزم أن تؤدي جميعها الأدوار نفسها؟","explain":"في نموذج النظير للنظير تتبادل الأجهزة الموارد مباشرة ويمكن للجهاز تقديم خدمة وطلب أخرى. في العميل والمزوّد يطلب العميل خدمات يوفرها المزوّد. بروتوكولات الاتصال تنظم التبادل، وتقسم البيانات إلى حزم تتضمن معلومات التوجيه وأجزاء المحتوى؛ يعاد تجميعها عند الوصول. لا يساوي النموذج هيكلية الاتصال.","example":"شبه المزوّد بمكتب خدمة والعميل بمن يطلب الخدمة، ثم أظهر أن المثال يشرح الأدوار فقط. قسم جملة إلى ثلاث بطاقات مرقمة؛ تصل بالترتيب 3 ثم 1 ثم 2، ويعيد المستقبل بناءها باستخدام الترقيم.","task":"صمم بطاقات حزم: المرسل، المستقبل، رقم الجزء والمحتوى. تبادلها داخل الفريق وأعد تجميع الرسالة، ثم قارن مثال مشاركة مباشرة بمثال مزوّد مركزي.","misconception":"يجب أن تصل أجزاء الرسالة بالترتيب نفسه الذي أرسلت به.","repair":"غير ترتيب بطاقات الوصول، ثم استخدم أرقامها لإعادة التجميع. ناقش أن المحاكاة تبسط آلية النقل.","game":"ساعي الحزم: لا يفوز الفريق إلا برسالة مكتملة مع تفسير دور عنوان الوجهة ورقم الجزء.","evidence":"يشرح دور العميل والمزوّد ويعيد تجميع رسالة ويذكر وظيفة قواعد الاتصال.","question":"ما الفرق بين النموذج والهيكلية في شبكة الصف؟","answer":"النموذج يوزع الخدمات والأدوار؛ الهيكلية تحدد كيفية توصيل الأجهزة.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","اسأل: إذا اتصلت أجهزة الصف بالطريقة نفسها، هل يلزم أن تؤدي جميعها الأدوار نفسها؟"],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","في نموذج النظير للنظير تتبادل الأجهزة الموارد مباشرة ويمكن للجهاز تقديم خدمة وطلب أخرى. في العميل والمزوّد يطلب العميل خدمات يوفرها المزوّد. بروتوكولات الاتصال تنظم التبادل، وتقسم البيانات إلى حزم تتضمن معلومات التوجيه وأجزاء المحتوى؛ يعاد تجميعها عند الوصول. لا يساوي النموذج هيكلية الاتصال. مثال المعلم: شبه المزوّد بمكتب خدمة والعميل بمن يطلب الخدمة، ثم أظهر أن المثال يشرح الأدوار فقط. قسم جملة إلى ثلاث بطاقات مرقمة؛ تصل بالترتيب 3 ثم 1 ثم 2، ويعيد المستقبل بناءها باستخدام الترقيم."],["15 دقائق","الحصة 2 · تطبيق وتعاون","صمم بطاقات حزم: المرسل، المستقبل، رقم الجزء والمحتوى. تبادلها داخل الفريق وأعد تجميع الرسالة، ثم قارن مثال مشاركة مباشرة بمثال مزوّد مركزي. النشاط التفاعلي المقترح: ساعي الحزم: لا يفوز الفريق إلا برسالة مكتملة مع تفسير دور عنوان الوجهة ورقم الجزء."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يشرح دور العميل والمزوّد ويعيد تجميع رسالة ويذكر وظيفة قواعد الاتصال. ويقدم تدخلًا عمليًا: غير ترتيب بطاقات الوصول، ثم استخدم أرقامها لإعادة التجميع. ناقش أن المحاكاة تبسط آلية النقل."],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: ما الفرق بين النموذج والهيكلية في شبكة الصف؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"review","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."}]},{"id":"g7-u3-l2","title":"اختيار جهاز الحاسوب وإصلاح الأنظمة","noorTitle":"اختيار جهاز الحاسوب وإصلاح الأنظمة","officialPeriods":2,"source":"دليل المعلم ص86–92","goalSource":"teacher-guide","quiz":[{"question":"ما نقطة البداية لاختيار جهاز؟","options":["الإعلان الأكثر لمعانًا","احتياج المستخدم وميزانيته","سعة التخزين وحدها"],"answer":1,"explanation":"نربط المواصفات بالمهمة قبل المقارنة."},{"question":"تطبيق واحد لا يستجيب؛ ما التصرف المناسب؟","options":["إغلاق مهام النظام المجهولة","فحصه وإغلاق التطبيق المعطل بإشراف المعلم","حذف ملفات النظام"],"answer":1,"explanation":"انتبه للعمل غير المحفوظ؛ لا تغلق مهام النظام المجهولة."},{"question":"رد الذكاء الاصطناعي يقترح إجراء غير مفهوم؛ ماذا تفعل؟","options":["أنفذه فورًا","أنشر بياناتي","أتوقف وأراجعه مع المعلم"],"answer":2,"explanation":"الاقتراح يحتاج مراجعة الأمان والملاءمة."}],"meetings":[{"id":"g7-u3-l2-m1","part":"1/1","title":"اختيار جهاز الحاسوب وإصلاح الأنظمة · لقاء 1/1","periods":[{"title":"اختر الجهاز من احتياج المستخدم","outcomes":[{"text":"اختيار جهاز الحاسوب المناسب للاحتياجات المختلفة."}],"reinforcement":false,"warm":"قدم أربع شخصيات: طالب، مسافر، مصمم، ولاعب. هل الجهاز الأغلى أفضل اختيار للجميع؟","explain":"نبدأ بالغرض والميزانية والاحتياجات ثم نقارن الجهاز. أداء المعالج وذاكرة RAM وقدرات الرسومات تؤثر في المهام، والتخزين يحفظ الملفات. سهولة الحمل والبطارية تهم المسافر، وكاميرا الويب والاتصال تهم التعلم عن بعد. إمكانية الوصول جزء من الملاءمة: تكبير النص وقارئ الشاشة والتباين قد تكون أهم من ميزة تسويقية.","example":"مسافر يقرأ مستندات ويحضر لقاءات قصيرة قد يفضل جهازًا خفيفًا ببطارية مناسبة؛ مصمم يعمل على ملفات كبيرة يحتاج أداء وذاكرة تناسب التطبيق. هذه مقارنة افتراضية وليست توصية شراء أو أسعارًا حقيقية.","task":"أنشئ جدولًا لثلاثة أجهزة افتراضية يقدمها المعلم وقارنها لحالة مستخدم. اكتب اختيارك وتنازلًا مقبولًا وسبب رفض البديل، وأضف حاجة وصول واحدة.","misconception":"زيادة سعة التخزين تعني دائمًا تشغيل البرامج أسرع.","repair":"قارن وظيفة RAM بوظيفة التخزين، واسأل عن مواصفة تؤثر في تشغيل البرامج مقابل حفظ الملفات.","game":"مستشار التقنية: يسحب الفريق بطاقة احتياج، ثم يقدم قرارًا خلال دقيقة؛ الفريق الآخر يسأل عن الميزانية أو سهولة الحمل.","evidence":"يربط ثلاثة معايير بالاحتياج ويبرر الاختيار ويذكر أثر إمكانية الوصول.","question":"هل يوجد جهاز واحد مثالي لكل المستخدمين؟","answer":"لا؛ الملاءمة تعتمد على الغرض والاحتياجات والميزانية، وتختلف بين المستخدمين.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","قدم أربع شخصيات: طالب، مسافر، مصمم، ولاعب. هل الجهاز الأغلى أفضل اختيار للجميع؟"],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","نبدأ بالغرض والميزانية والاحتياجات ثم نقارن الجهاز. أداء المعالج وذاكرة RAM وقدرات الرسومات تؤثر في المهام، والتخزين يحفظ الملفات. سهولة الحمل والبطارية تهم المسافر، وكاميرا الويب والاتصال تهم التعلم عن بعد. إمكانية الوصول جزء من الملاءمة: تكبير النص وقارئ الشاشة والتباين قد تكون أهم من ميزة تسويقية. مثال المعلم: مسافر يقرأ مستندات ويحضر لقاءات قصيرة قد يفضل جهازًا خفيفًا ببطارية مناسبة؛ مصمم يعمل على ملفات كبيرة يحتاج أداء وذاكرة تناسب التطبيق. هذه مقارنة افتراضية وليست توصية شراء أو أسعارًا حقيقية."],["15 دقائق","الحصة 1 · تطبيق وتعاون","أنشئ جدولًا لثلاثة أجهزة افتراضية يقدمها المعلم وقارنها لحالة مستخدم. اكتب اختيارك وتنازلًا مقبولًا وسبب رفض البديل، وأضف حاجة وصول واحدة. النشاط التفاعلي المقترح: مستشار التقنية: يسحب الفريق بطاقة احتياج، ثم يقدم قرارًا خلال دقيقة؛ الفريق الآخر يسأل عن الميزانية أو سهولة الحمل."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يربط ثلاثة معايير بالاحتياج ويبرر الاختيار ويذكر أثر إمكانية الوصول. ويقدم تدخلًا عمليًا: قارن وظيفة RAM بوظيفة التخزين، واسأل عن مواصفة تؤثر في تشغيل البرامج مقابل حفظ الملفات."],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: هل يوجد جهاز واحد مثالي لكل المستخدمين؟ ثم يوثق خطوة تحسين."]]},{"title":"شخص المشكلة قبل تجربة الحل","outcomes":[{"text":"استكشاف كيفية حل مشكلات الحاسوب والإنترنت وشبكات الواي فاي الشائعة."},{"text":"استخدام الذكاء الاصطناعي التوليدي للمساعدة في اكتشاف مشكلات الحاسوب واقتراح حلول لها."}],"reinforcement":false,"warm":"اعرض حالتين: تطبيق متوقف والمؤشر يتحرك؛ جهاز لا يستجيب بالكامل. لماذا لا نبدأ بالإجراء نفسه؟","explain":"حدد العرض وما الذي تغير، ثم افحص الأسباب البسيطة خطوة خطوة. التطبيق المتوقف يمكن إغلاقه من مدير المهام بإشراف المعلم مع الانتباه للعمل غير المحفوظ؛ لا تغلق مهام النظام المجهولة. في مشكلات الاتصال افحص اتصال الجهاز ووضع الطيران وقارن جهازًا آخر. الذكاء الاصطناعي يقترح احتمالات، وليس تشخيصًا مضمونًا؛ راجع الأمان والملاءمة قبل تنفيذ أي خطوة.","example":"توجيه جيد: جهاز ويندوز متصل بالواي فاي لكن المتصفح لا يفتح الصفحات؛ الأجهزة الأخرى تعمل، ووضع الطيران متوقف. اقترح فحوصًا بسيطة وآمنة لطالب سابع، واشرح سبب كل خطوة. لا يتضمن التوجيه كلمة المرور أو بيانات خاصة.","task":"رتب بطاقات تشخيص لفأرة لا تعمل أو لوحة مفاتيح أو اتصال متوقف. سجل العرض، الفحص، النتيجة، القرار. راجع ردًا افتراضيًا للذكاء الاصطناعي وميز خطوة مناسبة وأخرى تستلزم مساعدة المعلم.","misconception":"كل اقتراح من مساعد الذكاء الاصطناعي صحيح ويمكن تنفيذه فورًا.","repair":"اجعل الطالب يسأل: هل الخطوة مرتبطة بالعرض؟ هل تفقد بيانات أو تتطلب صلاحيات؟ هل يوجد فحص أبسط؟","game":"عيادة الأعطال: الفرق تتبادل تذاكر مشكلات افتراضية. نقطة للسؤال التشخيصي ونقطة للحل الآمن المبرر.","evidence":"يصف المشكلة ويختار فحصًا آمنًا ويكتب توجيهًا واضحًا دون بيانات شخصية.","question":"لماذا نجرب تغييرًا واحدًا كل مرة؟","answer":"لنعرف أثره ونتحقق من سبب المشكلة بدل خلط النتائج.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","اعرض حالتين: تطبيق متوقف والمؤشر يتحرك؛ جهاز لا يستجيب بالكامل. لماذا لا نبدأ بالإجراء نفسه؟"],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","حدد العرض وما الذي تغير، ثم افحص الأسباب البسيطة خطوة خطوة. التطبيق المتوقف يمكن إغلاقه من مدير المهام بإشراف المعلم مع الانتباه للعمل غير المحفوظ؛ لا تغلق مهام النظام المجهولة. في مشكلات الاتصال افحص اتصال الجهاز ووضع الطيران وقارن جهازًا آخر. الذكاء الاصطناعي يقترح احتمالات، وليس تشخيصًا مضمونًا؛ راجع الأمان والملاءمة قبل تنفيذ أي خطوة. مثال المعلم: توجيه جيد: جهاز ويندوز متصل بالواي فاي لكن المتصفح لا يفتح الصفحات؛ الأجهزة الأخرى تعمل، ووضع الطيران متوقف. اقترح فحوصًا بسيطة وآمنة لطالب سابع، واشرح سبب كل خطوة. لا يتضمن التوجيه كلمة المرور أو بيانات خاصة."],["15 دقائق","الحصة 2 · تطبيق وتعاون","رتب بطاقات تشخيص لفأرة لا تعمل أو لوحة مفاتيح أو اتصال متوقف. سجل العرض، الفحص، النتيجة، القرار. راجع ردًا افتراضيًا للذكاء الاصطناعي وميز خطوة مناسبة وأخرى تستلزم مساعدة المعلم. النشاط التفاعلي المقترح: عيادة الأعطال: الفرق تتبادل تذاكر مشكلات افتراضية. نقطة للسؤال التشخيصي ونقطة للحل الآمن المبرر."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يصف المشكلة ويختار فحصًا آمنًا ويكتب توجيهًا واضحًا دون بيانات شخصية. ويقدم تدخلًا عمليًا: اجعل الطالب يسأل: هل الخطوة مرتبطة بالعرض؟ هل تفقد بيانات أو تتطلب صلاحيات؟ هل يوجد فحص أبسط؟"],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: لماذا نجرب تغييرًا واحدًا كل مرة؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"review","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."}]},{"id":"g7-u3-l3","title":"المواطنة الرقمية","noorTitle":"المواطنة الرقمية","officialPeriods":2,"source":"دليل المعلم ص93–97","goalSource":"teacher-guide","quiz":[{"question":"خبر قديم يعاد نشره كحدث اليوم؛ ما الفحص المهم؟","options":["عدد الإعجابات","تاريخ الحدث وسياق النشر","لون العنوان"],"answer":1,"explanation":"قد يكون الخبر صحيحًا في وقته ومضللًا في سياقه الجديد."},{"question":"هل ذكر المصدر وحده يسمح بكل استخدام؟","options":["نعم دائمًا","لا؛ أفحص الإذن وشروط الاستخدام","لا حاجة للمصدر"],"answer":1,"explanation":"احترام الحقوق يتطلب نسبة العمل وفحص شروط استخدامه."},{"question":"تطلب رسالة جائزة رقم الهوية؛ ما القرار؟","options":["أرسل بسرعة","أطلب جائزة أكبر","لا أرسل البيانات وأستعين بشخص موثوق"],"answer":2,"explanation":"لا تشارك البيانات الشخصية مع الغرباء أو المواقع غير المعروفة."}],"meetings":[{"id":"g7-u3-l3-m1","part":"1/1","title":"المواطنة الرقمية · لقاء 1/1","periods":[{"title":"خصوصيتي وحقوق الآخرين","outcomes":[{"text":"التعرف إلى مفهوم المواطنة الرقمية."},{"text":"حماية البيانات الشخصية واحترام حقوق الملكية الفكرية."},{"text":"تطبيق قواعد آداب السلوك على الإنترنت."}],"reinforcement":false,"warm":"قدم رسالة افتراضية تطلب اسم الطالب ورقم الهاتف مقابل جائزة. ما المعلومات التي يحتاج إلى حمايتها؟ لا تطلب بيانات حقيقية.","explain":"المواطنة الرقمية استخدام مسؤول وآمن ومحترم للتقنية؛ تشمل الخصوصية والحقوق وتقييم المعلومات والسلوك. البيانات الشخصية مثل الاسم الكامل ورقم الهاتف والهوية تحتاج إلى حماية عند التعامل مع الغرباء والمواقع غير المعروفة. حقوق الملكية الفكرية تخص صاحب العمل؛ ذكر المصدر مهم، لكنه لا يحل وحده محل الإذن أو شروط الترخيص.","example":"طالب يريد صورة لعرضه: يختار صورة مسموحًا باستخدامها وفق شروطها، يسجل صاحبها ومصدرها، وينسبها بوضوح. إذا لم يعرف شروط استخدامها، يستبدلها بمادة من إنشائه أو يستعين بالمعلم. في الحوار الرقمي يرد على الفكرة بأدب دون إهانة صاحبها.","task":"صنف بطاقات مشاركة إلى آمن أو يحتاج تحققًا أو لا يشارك مع الغريب. أعد صياغة تعليق جارح إلى رد محترم، وأنشئ بطاقة مصدر لصورة افتراضية مع شرط الاستخدام.","misconception":"كل صورة على الإنترنت مجانية ويمكن استخدامها بمجرد كتابة اسم الموقع.","repair":"افصل بين الوصول إلى الصورة وبين حق إعادة استخدامها. اطلب فحص الإذن أو الترخيص مع توثيق المصدر.","game":"إشارة المرور الرقمية: اللون يحدد القرار، والتعليل يحدد النقطة. استخدم مواقف وهمية دون معلومات الطلبة.","evidence":"يميز البيانات الشخصية ويقترح ردًا محترمًا ويشرح احترام المصدر والإذن.","question":"هل تكفي عبارة «من الإنترنت» لتوثيق صورة؟","answer":"لا؛ يلزم مصدر محدد ونسبة العمل لصاحبه والتحقق من شروط الاستخدام.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","قدم رسالة افتراضية تطلب اسم الطالب ورقم الهاتف مقابل جائزة. ما المعلومات التي يحتاج إلى حمايتها؟ لا تطلب بيانات حقيقية."],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","المواطنة الرقمية استخدام مسؤول وآمن ومحترم للتقنية؛ تشمل الخصوصية والحقوق وتقييم المعلومات والسلوك. البيانات الشخصية مثل الاسم الكامل ورقم الهاتف والهوية تحتاج إلى حماية عند التعامل مع الغرباء والمواقع غير المعروفة. حقوق الملكية الفكرية تخص صاحب العمل؛ ذكر المصدر مهم، لكنه لا يحل وحده محل الإذن أو شروط الترخيص. مثال المعلم: طالب يريد صورة لعرضه: يختار صورة مسموحًا باستخدامها وفق شروطها، يسجل صاحبها ومصدرها، وينسبها بوضوح. إذا لم يعرف شروط استخدامها، يستبدلها بمادة من إنشائه أو يستعين بالمعلم. في الحوار الرقمي يرد على الفكرة بأدب دون إهانة صاحبها."],["15 دقائق","الحصة 1 · تطبيق وتعاون","صنف بطاقات مشاركة إلى آمن أو يحتاج تحققًا أو لا يشارك مع الغريب. أعد صياغة تعليق جارح إلى رد محترم، وأنشئ بطاقة مصدر لصورة افتراضية مع شرط الاستخدام. النشاط التفاعلي المقترح: إشارة المرور الرقمية: اللون يحدد القرار، والتعليل يحدد النقطة. استخدم مواقف وهمية دون معلومات الطلبة."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يميز البيانات الشخصية ويقترح ردًا محترمًا ويشرح احترام المصدر والإذن. ويقدم تدخلًا عمليًا: افصل بين الوصول إلى الصورة وبين حق إعادة استخدامها. اطلب فحص الإذن أو الترخيص مع توثيق المصدر."],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: هل تكفي عبارة «من الإنترنت» لتوثيق صورة؟ ثم يوثق خطوة تحسين."]]},{"title":"تحقق قبل أن تشارك","outcomes":[{"text":"تقييم المعلومات المنشورة على الإنترنت وتحديد المصادر غير الموثوقة."},{"text":"التعامل مع الأخبار والصور ومقاطع الفيديو المزيفة."}],"reinforcement":false,"warm":"اعرض خبرًا افتراضيًا بعنوان مثير وتاريخ قديم. هل عدد المشاركات دليل على صحته؟","explain":"نقيم المصدر والكاتب والدقة والتحديث والموضوعية. نفحص تاريخ الخبر والسياق والعنوان والأدلة ونقارن بمصدرين أو ثلاثة موثوقة كما يقترح الدليل. الخبر القديم قد يكون صحيحًا في وقته لكنه مضلل إذا قدم كحدث جديد. الصورة الواقعية أو المحتوى المولد لا يثبتان وقوع الحدث. نميز الواقعة القابلة للتحقق عن الرأي.","example":"صفحة تقول إن موعد نشاط المدرسة تغير دون اسم مسؤول أو تاريخ. يوقف الطالب المشاركة ويقارن بالإعلان الرسمي ويسأل المعلم. الجاذبية البصرية ليست توثيقًا. خبر قديم معاد النشر يحتاج مراجعة تاريخ الحدث والنشر.","task":"حقق في صفحتين افتراضيتين يعدهما المعلم: كاتب، تاريخ، مصدر، دليل وغرض. اكتب قرار نشر أو توقف مع سببين، ثم حدد ما الذي يلزم للحصول على ثقة أكبر.","misconception":"إذا تكرر الخبر في عدة حسابات فهو مؤكد.","repair":"قد تنقل الحسابات المصدر نفسه. ابحث عن أدلة مستقلة ومصدر موثوق وتاريخ واضح.","game":"غرفة الأخبار: أدوار محرر ومدقق ومراجع مصادر؛ لا ينشر الفريق بطاقة الخبر قبل اكتمال قائمة التحقق.","evidence":"يفحص المعايير ويذكر سببًا للتوقف ويميز رأيًا عن واقعة.","question":"ماذا تفعل إذا لم تجد دليلًا موثوقًا؟","answer":"أتوقف عن المشاركة وأبحث أو أطلب المساعدة؛ لا أملأ الفراغ بالتخمين.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","اعرض خبرًا افتراضيًا بعنوان مثير وتاريخ قديم. هل عدد المشاركات دليل على صحته؟"],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","نقيم المصدر والكاتب والدقة والتحديث والموضوعية. نفحص تاريخ الخبر والسياق والعنوان والأدلة ونقارن بمصدرين أو ثلاثة موثوقة كما يقترح الدليل. الخبر القديم قد يكون صحيحًا في وقته لكنه مضلل إذا قدم كحدث جديد. الصورة الواقعية أو المحتوى المولد لا يثبتان وقوع الحدث. نميز الواقعة القابلة للتحقق عن الرأي. مثال المعلم: صفحة تقول إن موعد نشاط المدرسة تغير دون اسم مسؤول أو تاريخ. يوقف الطالب المشاركة ويقارن بالإعلان الرسمي ويسأل المعلم. الجاذبية البصرية ليست توثيقًا. خبر قديم معاد النشر يحتاج مراجعة تاريخ الحدث والنشر."],["15 دقائق","الحصة 2 · تطبيق وتعاون","حقق في صفحتين افتراضيتين يعدهما المعلم: كاتب، تاريخ، مصدر، دليل وغرض. اكتب قرار نشر أو توقف مع سببين، ثم حدد ما الذي يلزم للحصول على ثقة أكبر. النشاط التفاعلي المقترح: غرفة الأخبار: أدوار محرر ومدقق ومراجع مصادر؛ لا ينشر الفريق بطاقة الخبر قبل اكتمال قائمة التحقق."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يفحص المعايير ويذكر سببًا للتوقف ويميز رأيًا عن واقعة. ويقدم تدخلًا عمليًا: قد تنقل الحسابات المصدر نفسه. ابحث عن أدلة مستقلة ومصدر موثوق وتاريخ واضح."],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: ماذا تفعل إذا لم تجد دليلًا موثوقًا؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"review","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."}]},{"id":"g7-u3-l4","title":"المشروع","noorTitle":"المشروع","officialPeriods":2,"source":"دليل المعلم ص98","goalSource":"teacher-guide","quiz":[{"question":"ما الدليل الأفضل على فائدة إعداد وصول؟","options":["كثرة الحركات","مقارنة موثقة قبل وبعد","اسم البرنامج فقط"],"answer":1,"explanation":"نسجل حاجة المستخدم وأثر الميزة وحدودها."},{"question":"ما الواجب بعد تجربة إعداد على جهاز التدريب؟","options":["إعادته إلى حالته الأصلية","تغيير كل الإعدادات","حذف سجل الفريق"],"answer":0,"explanation":"التوثيق وإعادة الحالة يحافظان على قابلية المقارنة والاستخدام."},{"question":"ما العرض الأقرب لهدف المشروع؟","options":["صور بلا تفسير","حاجة وميزات مجربة ونتائج ومصادر","مؤثرات فقط"],"answer":1,"explanation":"المشروع يفسر إمكانية الوصول بأدلة وليس بالزينة."}],"meetings":[{"id":"g7-u3-l4-m1","part":"1/1","title":"المشروع · لقاء 1/1","periods":[{"title":"تقنية يمكن للجميع استخدامها","outcomes":[{"text":"اختيار جهاز الحاسوب المناسب للاحتياجات المختلفة."},{"text":"استخدام الذكاء الاصطناعي التوليدي للمساعدة في اكتشاف مشكلات الحاسوب واقتراح حلول لها."},{"text":"تقييم المعلومات المنشورة على الإنترنت وتحديد المصادر غير الموثوقة."}],"reinforcement":false,"warm":"اعرض النص نفسه بحجمين وتباينين مختلفين. أي نسخة أسهل للقراءة، ولمن؟ لا تحاكي إعاقة بطريقة ساخرة ولا تطلب معلومات صحية عن الطلبة.","explain":"مشروع الدليل يستكشف إمكانية الوصول للأشخاص ذوي الإعاقة البصرية. تبحث المجموعة عن صعوبات استخدام التقنية، ثم تختبر تكبير النص أو المكبر أو التباين أو قارئ الشاشة بإشراف المعلم، وتوثق أثر الإعداد. اقتراح الذكاء الاصطناعي بداية قابلة للمراجعة، لا بديل عن اختبار الإعداد ومصدره.","example":"على جهاز تدريب، افتح إعدادًا معتمدًا مسبقًا من المعلم، سجل الوضع الأصلي ثم عدل حجم النص ولاحظ القراءة؛ أعد الإعداد إلى حالته بعد الاختبار. وثق: الحاجة، الميزة، الخطوة، النتيجة، حدود الفائدة. تختلف المسارات حسب نظام الجهاز.","task":"في فريق من 3–5: باحث ومنفذ وملاحظ ومصمم ومقدم بحسب العدد. اختبر ميزتين معتمدتين فقط، وسجل الأثر قبل وبعد ومصدر الشرح. اكتب توجيهًا عامًا يطلب خطوات دون أسماء أو معلومات صحية.","misconception":"ميزة الوصول تخص شخصًا واحدًا ولا تفيد سواه.","repair":"ناقش كيف يفيد تكبير النص مستخدمين مختلفين، مع عدم افتراض أن حلًا واحدًا يناسب كل الاحتياجات.","game":"مختبر الشمول: يمنح الفريق بطاقة دليل لكل نتيجة ملاحظة، ولا يكفي قول «أفضل» دون وصف.","evidence":"يوثق اختبارًا قابلًا للمراجعة ويبرر ارتباط الميزة بالحاجة.","question":"لماذا نسجل الإعداد الأصلي؟","answer":"لإعادة جهاز التدريب كما كان ولإجراء مقارنة واضحة قبل وبعد.","steps":[["5 دقائق","الحصة 1 · تهيئة واسترجاع","اعرض النص نفسه بحجمين وتباينين مختلفين. أي نسخة أسهل للقراءة، ولمن؟ لا تحاكي إعاقة بطريقة ساخرة ولا تطلب معلومات صحية عن الطلبة."],["10 دقائق","الحصة 1 · نمذجة وشرح متدرج","مشروع الدليل يستكشف إمكانية الوصول للأشخاص ذوي الإعاقة البصرية. تبحث المجموعة عن صعوبات استخدام التقنية، ثم تختبر تكبير النص أو المكبر أو التباين أو قارئ الشاشة بإشراف المعلم، وتوثق أثر الإعداد. اقتراح الذكاء الاصطناعي بداية قابلة للمراجعة، لا بديل عن اختبار الإعداد ومصدره. مثال المعلم: على جهاز تدريب، افتح إعدادًا معتمدًا مسبقًا من المعلم، سجل الوضع الأصلي ثم عدل حجم النص ولاحظ القراءة؛ أعد الإعداد إلى حالته بعد الاختبار. وثق: الحاجة، الميزة، الخطوة، النتيجة، حدود الفائدة. تختلف المسارات حسب نظام الجهاز."],["15 دقائق","الحصة 1 · تطبيق وتعاون","في فريق من 3–5: باحث ومنفذ وملاحظ ومصمم ومقدم بحسب العدد. اختبر ميزتين معتمدتين فقط، وسجل الأثر قبل وبعد ومصدر الشرح. اكتب توجيهًا عامًا يطلب خطوات دون أسماء أو معلومات صحية. النشاط التفاعلي المقترح: مختبر الشمول: يمنح الفريق بطاقة دليل لكل نتيجة ملاحظة، ولا يكفي قول «أفضل» دون وصف."],["7 دقائق","الحصة 1 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يوثق اختبارًا قابلًا للمراجعة ويبرر ارتباط الميزة بالحاجة. ويقدم تدخلًا عمليًا: ناقش كيف يفيد تكبير النص مستخدمين مختلفين، مع عدم افتراض أن حلًا واحدًا يناسب كل الاحتياجات."],["3 دقائق","الحصة 1 · خروج وتوثيق","يجيب الطالب: لماذا نسجل الإعداد الأصلي؟ ثم يوثق خطوة تحسين."]]},{"title":"عرض قصير بأدلة واضحة","outcomes":[{"text":"اختيار جهاز الحاسوب المناسب للاحتياجات المختلفة."},{"text":"استخدام الذكاء الاصطناعي التوليدي للمساعدة في اكتشاف مشكلات الحاسوب واقتراح حلول لها."},{"text":"حماية البيانات الشخصية واحترام حقوق الملكية الفكرية."},{"text":"تقييم المعلومات المنشورة على الإنترنت وتحديد المصادر غير الموثوقة."},{"text":"تطبيق قواعد آداب السلوك على الإنترنت."}],"reinforcement":false,"warm":"اعرض شريحة مزدحمة وأخرى واضحة؛ هل حديثنا عن إمكانية الوصول يظهر في تصميم عرضنا؟","explain":"ينظم الفريق النتائج في عرض قصير باستخدام أداة مناسبة مثل PowerPoint. يوضح المشكلة والميزات المجربة والنتائج والمصادر، ويستخدم خطًا مقروءًا وتباينًا جيدًا وترتيبًا واضحًا. يذكر دور الذكاء الاصطناعي إن استخدم ويبين كيف راجع اقتراحاته. يشارك جميع الأعضاء ويتقبلون التغذية الراجعة ثم يحسنون المنتج.","example":"عرض من أربع شرائح مقترحة: حاجة المستخدم، الميزتان والخطوات، دليل قبل وبعد، خلاصة ومصادر. عدد الشرائح تنظيم مقترح وليس شرطًا رسميًا. يقدم كل عضو تفسيرًا لقرار أو نتيجة.","task":"جهز العرض وقدم دقيقتين لكل فريق بحسب وقت الصف. تستخدم الفرق بطاقة مراجعة: وضوح الحاجة، صحة التجربة، مصادر واحترام الحقوق، قابلية القراءة، مشاركة الأعضاء. عدل نقطة واحدة واحتفظ بدليل التحسين.","misconception":"العرض الجيد يعتمد على كثرة الحركات والصور.","repair":"اجعل الطالب يختبر القراءة من آخر الصف ثم يحذف عنصرًا مشتتًا. اربط الشكل بفهم المحتوى.","game":"معرض التقنية الشاملة: زميل يعطي نقطة قوة واقتراحًا محددًا؛ وسام التعزيز لمن يحسن بدليل أو يساعد زميلًا.","evidence":"يشرح أثر ميزة وصول ويعرض مصدرًا ومقارنة ومساهمة شخصية.","question":"كيف نعرف أن المشروع ساعد في الفهم؟","answer":"بنتيجة اختبار موثقة وتفسير الحاجة وتحسن واضح بعد المراجعة، لا بالمؤثرات وحدها.","steps":[["5 دقائق","الحصة 2 · تهيئة واسترجاع","اعرض شريحة مزدحمة وأخرى واضحة؛ هل حديثنا عن إمكانية الوصول يظهر في تصميم عرضنا؟"],["10 دقائق","الحصة 2 · نمذجة وشرح متدرج","ينظم الفريق النتائج في عرض قصير باستخدام أداة مناسبة مثل PowerPoint. يوضح المشكلة والميزات المجربة والنتائج والمصادر، ويستخدم خطًا مقروءًا وتباينًا جيدًا وترتيبًا واضحًا. يذكر دور الذكاء الاصطناعي إن استخدم ويبين كيف راجع اقتراحاته. يشارك جميع الأعضاء ويتقبلون التغذية الراجعة ثم يحسنون المنتج. مثال المعلم: عرض من أربع شرائح مقترحة: حاجة المستخدم، الميزتان والخطوات، دليل قبل وبعد، خلاصة ومصادر. عدد الشرائح تنظيم مقترح وليس شرطًا رسميًا. يقدم كل عضو تفسيرًا لقرار أو نتيجة."],["15 دقائق","الحصة 2 · تطبيق وتعاون","جهز العرض وقدم دقيقتين لكل فريق بحسب وقت الصف. تستخدم الفرق بطاقة مراجعة: وضوح الحاجة، صحة التجربة، مصادر واحترام الحقوق، قابلية القراءة، مشاركة الأعضاء. عدل نقطة واحدة واحتفظ بدليل التحسين. النشاط التفاعلي المقترح: معرض التقنية الشاملة: زميل يعطي نقطة قوة واقتراحًا محددًا؛ وسام التعزيز لمن يحسن بدليل أو يساعد زميلًا."],["7 دقائق","الحصة 2 · مراجعة وتصحيح","يراجع المعلم الدليل التالي: يشرح أثر ميزة وصول ويعرض مصدرًا ومقارنة ومساهمة شخصية. ويقدم تدخلًا عمليًا: اجعل الطالب يختبر القراءة من آخر الصف ثم يحذف عنصرًا مشتتًا. اربط الشكل بفهم المحتوى."],["3 دقائق","الحصة 2 · خروج وتوثيق","يجيب الطالب: كيف نعرف أن المشروع ساعد في الفهم؟ ثم يوثق خطوة تحسين."]]}],"goalBinding":"review","parentNote":"اسأل الطالب عن قرار اتخذه وسببه ودليل تحسن تعلمه. شجعه على الشرح والمراجعة دون تنفيذ المهمة عنه."}]}]}]},{"id":"g5-it-s1","grade":5,"subject":"تقنية المعلومات","semester":1,"title":"تقنية المعلومات · الصف 5","status":"planned","units":[]},{"id":"g6-it-s1","grade":6,"subject":"تقنية المعلومات","semester":1,"title":"تقنية المعلومات · الصف 6","status":"planned","units":[]},{"id":"g9-it-s1","grade":9,"subject":"تقنية المعلومات","semester":1,"title":"تقنية المعلومات · الصف 9","status":"planned","units":[]}]};
